/* ----------------------------------------------------------- arg helpers */
/* Collect a WORD_LIST into argv-ish vector (NULL-terminated). Caller frees. */
static char **
bsdg_argv (WORD_LIST *l, int *argc_out)
{
    int n = 0; for (WORD_LIST *p = l; p; p = p->next) n++;
    char **v = malloc ((n + 1) * sizeof *v);
    if (!v) return NULL;
    int i = 0; for (WORD_LIST *p = l; p; p = p->next) v[i++] = p->word->word;
    v[i] = NULL; if (argc_out) *argc_out = n;
    return v;
}

/* ----------------------------------------------------------------- primes */
static int
bsdg_is_prime (uint64_t n)
{
    if (n < 2) return 0;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    for (uint64_t i = 5; i * i <= n; i += 6)
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    return 1;
}
static int
game_primes (int argc, char **argv)
{
    uint64_t start = 0, stop = 0; int have_stop = 0;
    char line[256];
    if (argc >= 1) {
        start = strtoull (argv[0], NULL, 10);
        if (argc >= 2) { stop = strtoull (argv[1], NULL, 10); have_stop = 1; }
    } else if (fgets (line, sizeof line, stdin)) {
        char *sp = NULL; start = strtoull (line, &sp, 10);
        if (sp) { while (*sp == ' ' || *sp == '\t') sp++;
                  if (*sp) { stop = strtoull (sp, NULL, 10); have_stop = 1; } }
    }
    if (!have_stop) stop = start + 1000;           /* bounded default window */
    if (stop < start) { builtin_error ("primes: stop < start"); return EXECUTION_FAILURE; }
    if (start < 2) start = 2;
    for (uint64_t n = start; n <= stop; n++)
        if (bsdg_is_prime (n)) printf ("%llu\n", (unsigned long long) n);
    return EXECUTION_SUCCESS;
}

/* ----------------------------------------------------------------- number */
static const char *ones[] = { "zero","one","two","three","four","five","six",
    "seven","eight","nine","ten","eleven","twelve","thirteen","fourteen",
    "fifteen","sixteen","seventeen","eighteen","nineteen" };
static const char *tens[] = { "","","twenty","thirty","forty","fifty","sixty",
    "seventy","eighty","ninety" };
static const char *scale[] = { "","thousand","million","billion","trillion",
    "quadrillion","quintillion" };
static void
spell_group (unsigned g, char *out, size_t cap)   /* 0..999 -> words */
{
    out[0] = '\0';
    if (g >= 100) { snprintf (out + strlen (out), cap - strlen (out), "%s hundred", ones[g / 100]); g %= 100; if (g) strncat (out, " ", cap - strlen (out) - 1); }
    if (g >= 20) { strncat (out, tens[g / 10], cap - strlen (out) - 1); g %= 10; if (g) strncat (out, " ", cap - strlen (out) - 1); }
    if (g > 0 && g < 20) strncat (out, ones[g], cap - strlen (out) - 1);
}
static int
game_number (int argc, char **argv)
{
    char buf[64]; const char *s;
    if (argc >= 1) s = argv[0];
    else { if (!fgets (buf, sizeof buf, stdin)) return EXECUTION_SUCCESS; buf[strcspn (buf, "\r\n")] = '\0'; s = buf; }
    while (*s == ' ' || *s == '\t') s++;
    int neg = 0; if (*s == '-') { neg = 1; s++; }
    if (*s == '+') s++;
    for (const char *q = s; *q; q++) if (!isdigit ((unsigned char) *q)) { builtin_error ("number: not an integer: %s", s); return EXECUTION_FAILURE; }
    unsigned long long v = strtoull (s, NULL, 10);
    if (v == 0) { printf ("zero\n"); return EXECUTION_SUCCESS; }
    unsigned groups[7]; int ng = 0;
    unsigned long long t = v; while (t && ng < 7) { groups[ng++] = (unsigned) (t % 1000); t /= 1000; }
    char out[1024]; out[0] = '\0';
    if (neg) strncat (out, "minus ", sizeof out - 1);
    for (int i = ng - 1; i >= 0; i--) {
        if (groups[i] == 0) continue;
        char g[128]; spell_group (groups[i], g, sizeof g);
        strncat (out, g, sizeof out - strlen (out) - 1);
        if (scale[i][0]) { strncat (out, " ", sizeof out - strlen (out) - 1); strncat (out, scale[i], sizeof out - strlen (out) - 1); }
        if (i > 0) strncat (out, " ", sizeof out - strlen (out) - 1);
    }
    printf ("%s\n", out);
    return EXECUTION_SUCCESS;
}

/* ------------------------------------------------------------------ morse */
static const char *morse_tab[36] = {
    /* 0-9 */ "-----",".----","..---","...--","....-",".....","-....","--...","---..","----.",
    /* a-z */ ".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--",
              "-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.." };
static const char *
morse_of (int ch)
{
    if (ch >= '0' && ch <= '9') return morse_tab[ch - '0'];
    if (ch >= 'a' && ch <= 'z') return morse_tab[10 + ch - 'a'];
    if (ch >= 'A' && ch <= 'Z') return morse_tab[10 + ch - 'A'];
    return NULL;
}
static void
morse_emit (const char *s)
{
    int started = 0;
    for (; *s; s++) {
        if (*s == ' ' || *s == '\t' || *s == '\n') {
            if (started) { fputs (" /", stdout); started = 2; }   /* word break */
            continue;
        }
        const char *m = morse_of ((unsigned char) *s);
        if (!m) continue;                            /* skip unknown chars */
        if (started) fputc (' ', stdout);
        fputs (m, stdout);
        started = 1;
    }
    if (started) fputc ('\n', stdout);
}
static int
game_morse (int argc, char **argv)
{
    if (argc >= 1) {
        size_t len = 0; for (int i = 0; i < argc; i++) len += strlen (argv[i]) + 1;
        char *j = malloc (len + 1); if (!j) return EXECUTION_FAILURE; j[0] = '\0';
        for (int i = 0; i < argc; i++) { if (i) strcat (j, " "); strcat (j, argv[i]); }
        morse_emit (j); free (j);
    } else {
        char line[1024];
        while (fgets (line, sizeof line, stdin)) morse_emit (line);
    }
    return EXECUTION_SUCCESS;
}

/* ------------------------------------------------------------ caesar/rot13 */
static int
caesar_filter (int shift)
{
    int c;
    shift = ((shift % 26) + 26) % 26;
    while ((c = getchar ()) != EOF) {
        if (c >= 'a' && c <= 'z') c = 'a' + (c - 'a' + shift) % 26;
        else if (c >= 'A' && c <= 'Z') c = 'A' + (c - 'A' + shift) % 26;
        putchar (c);
    }
    return EXECUTION_SUCCESS;
}
static int
caesar_text (const char *s, int shift)
{
    shift = ((shift % 26) + 26) % 26;
    for (; *s; s++) {
        int c = (unsigned char) *s;
        if (c >= 'a' && c <= 'z') c = 'a' + (c - 'a' + shift) % 26;
        else if (c >= 'A' && c <= 'Z') c = 'A' + (c - 'A' + shift) % 26;
        putchar (c);
    }
    putchar ('\n');
    return EXECUTION_SUCCESS;
}
static int
game_caesar (int argc, char **argv)
{
    int shift = 13;                  /* default; BSD guesses, we take explicit */
    int ai = 0;
    if (argc >= 1) { char *e; long v = strtol (argv[0], &e, 10); if (*e == '\0') { shift = (int) v; ai = 1; } }
    if (argc > ai) {                 /* remaining args = text */
        size_t len = 0; for (int i = ai; i < argc; i++) len += strlen (argv[i]) + 1;
        char *j = malloc (len + 1); if (!j) return EXECUTION_FAILURE; j[0] = '\0';
        for (int i = ai; i < argc; i++) { if (i > ai) strcat (j, " "); strcat (j, argv[i]); }
        int rr = caesar_text (j, shift); free (j); return rr;
    }
    return caesar_filter (shift);
}
static int
game_rot13 (int argc, char **argv)
{
    if (argc >= 1) {
        size_t len = 0; for (int i = 0; i < argc; i++) len += strlen (argv[i]) + 1;
        char *j = malloc (len + 1); if (!j) return EXECUTION_FAILURE; j[0] = '\0';
        for (int i = 0; i < argc; i++) { if (i) strcat (j, " "); strcat (j, argv[i]); }
        int rr = caesar_text (j, 13); free (j); return rr;
    }
    return caesar_filter (13);
}

