static void bg_banner_usage (void) {
    fputs ("usage: banner [-w width] [-t] [message ...]\n", stderr);
}

/* Render one already-validated message into print[]-masked rows on stdout.
 * print[] selects which of the 132 columns survive the -w scrunch. */
static int bg_banner_render (const char *message, int nchars,
                             const unsigned char *prnt, int trace) {
    char line[BG_BANNER_DWIDTH];
    int i, j, linen, max, pc, term, x, y;

    for (i = 0; i < nchars; i++) {
        unsigned char uc = (unsigned char) message[i];
        if (trace)
            fprintf (stderr, "banner: char #%d: %c\n", i, message[i]);
        for (j = 0; j < BG_BANNER_DWIDTH; j++)
            line[j] = ' ';
        pc = bg_banner_asc[uc];
        term = 0;
        max = 0;
        linen = 0;
        while (!term) {
            if (pc < 0 || pc >= BG_BANNER_NBYTES) {
                fprintf (stderr, "banner: internal table error (pc=%d)\n", pc);
                return 1;
            }
            x = bg_banner_data[pc] & 0377;
            if (x >= 128) {
                if (x > 192)
                    term++;
                x = x & 63;
                while (x--) {
                    if (linen < BG_BANNER_DWIDTH && prnt[linen]) {
                        for (j = 0; j <= max && j < BG_BANNER_DWIDTH; j++)
                            if (prnt[j])
                                putchar (line[j]);
                        putchar ('\n');
                    }
                    linen++;
                }
                for (j = 0; j < BG_BANNER_DWIDTH; j++)
                    line[j] = ' ';
                pc++;
            } else {
                y = bg_banner_data[pc + 1] & 0377;
                max = x + y;
                if (max > BG_BANNER_DWIDTH)
                    max = BG_BANNER_DWIDTH;
                while (x < max)
                    line[x++] = '#';
                pc += 2;
            }
        }
    }
    return 0;
}

static int bsdg_banner (int argc, char **argv) {
    char message[BG_BANNER_MAXMSG];
    unsigned char prnt[BG_BANNER_DWIDTH];
    int width = BG_BANNER_DWIDTH;
    int trace = 0;
    int i, j, nchars;
    int ai = 0;

    /* Option scan. argv[0] is already the first arg (game name stripped). */
    while (ai < argc && argv[ai][0] == '-' && argv[ai][1] != '\0') {
        const char *o = argv[ai];
        if (strcmp (o, "--") == 0) { ai++; break; }
        if (strcmp (o, "-h") == 0 || strcmp (o, "--help") == 0) {
            bg_banner_usage ();
            return 0;
        }
        if (strcmp (o, "-w") == 0) {
            if (ai + 1 >= argc) {
                fprintf (stderr, "banner: option -w requires an argument\n");
                return 2;
            }
            width = atoi (argv[++ai]);
            if (width <= 0) {
                fprintf (stderr, "banner: illegal argument for -w option\n");
                return 1;
            }
            ai++;
            continue;
        }
        /* combined single-char flags: -t, -d (debug==trace here) */
        {
            const char *p = o + 1;
            int bad = 0;
            for (; *p; p++) {
                if (*p == 't' || *p == 'd') trace = 1;
                else { bad = 1; break; }
            }
            if (bad) { bg_banner_usage (); return 2; }
        }
        ai++;
    }

    /* Build the column mask for -w scrunch (default width keeps all 132). */
    for (j = 0; j < BG_BANNER_DWIDTH; j++)
        prnt[j] = 0;
    for (i = 0; i < width; i++) {
        j = i * BG_BANNER_DWIDTH / width;
        if (j >= 0 && j < BG_BANNER_DWIDTH)
            prnt[j] = 1;
    }

    /* Gather the message: remaining argv joined by spaces, else one stdin line. */
    if (ai < argc) {
        size_t room = sizeof message - 1;
        message[0] = '\0';
        for (; ai < argc; ai++) {
            if (message[0] != '\0') {
                size_t l = strlen (message);
                if (l < room) { message[l] = ' '; message[l + 1] = '\0'; }
            }
            strncat (message, argv[ai], room - strlen (message));
        }
        nchars = (int) strlen (message);
    } else {
        if (isatty (0))
            fputs ("Message: ", stderr);
        if (!fgets (message, sizeof message, stdin))
            return 0;                 /* empty input -> nothing to print */
        nchars = (int) strlen (message);
        while (nchars > 0 &&
               (message[nchars - 1] == '\n' || message[nchars - 1] == '\r'))
            message[--nchars] = '\0';
    }

    /* Validate every character is in the font before printing anything. */
    {
        int bad = 0;
        for (i = 0; i < nchars; i++) {
            unsigned char uc = (unsigned char) message[i];
            if (uc >= BG_BANNER_NCHARS || bg_banner_asc[uc] == 0) {
                fprintf (stderr,
                         "banner: the character '%c' is not in my character set\n",
                         message[i]);
                bad++;
            }
        }
        if (bad)
            return 1;
    }

    if (trace)
        fprintf (stderr, "banner: message '%s' is OK (%d chars)\n",
                 message, nchars);

    return bg_banner_render (message, nchars, prnt, trace);
}

/* ===== battlestar.c ===== */
/* @game battlestar : a tropical/stellar text adventure -- explore, take/drop, fight */
/* bsdgames `battlestar`: "a stellar-tropical adventure game" originally written
 * by Adm. David W. Riggle on the Cory PDP-11/70 at UC Berkeley. The full game is
 * a 275-room island/spaceship odyssey with a rich English verb parser, a
 * day/night world, combat, fuel/flight, weight/encumbrance, scoring and saved
 * games. That is far too large to port verbatim under the no-include / static /
 * single-file adapter contract, so this is a *bounded but genuinely working*
 * fresh C rewrite of the engine's core:
 *
 *   - A real room/location graph: the battlestar interior (rooms 1..27 from the
 *     upstream dayfile -- the main hangar, landing bay, gallery, control room,
 *     launch room, viper tubes, the executive staterooms, sick bay, armory,
 *     magazine, presidential suite, etc.). Room *names* are verbatim from the
 *     upstream dayfile[]; descriptions are faithfully paraphrased with the
 *     compass exits spelled out (the upstream dash/plus/star facing markers are
 *     replaced by absolute exits, see SCOPE below). Links outside the ported
 *     subset are pruned to "no exit".
 *   - Absolute movement n/s/e/w/u/d (plus the long words north/south/...). The
 *     upstream facing-relative ahead/back/left/right scheme is intentionally NOT
 *     ported; see SCOPE.
 *   - look, take/get, drop, inventory (i/inven), and a real verb/word parser
 *     built from the upstream wlist[] (verbs, objects, nouns, conjunctions,
 *     adjectives) -- adjectives are stripped, "and"/"," chain objects, "take
 *     everything" works, unknown words yield the upstream "WORD: How's that?".
 *   - A few starting objects placed via the upstream dayobjs[] map (knife,
 *     maid's body, viper, robe, amulet, laser, ...), each with its verbatim
 *     long ("There is a knife here.") and short ("knife") descriptions and
 *     weight/cumber, so take/drop/inventory enforce MAXWEIGHT/MAXCUMBER.
 *   - kill/fight + attack/smite verbs: a minimal deterministic combat stub
 *     against the in-room woodsman/elf so "fight" is more than a no-op.
 *
 * This is enough to explore the ship, pick up the maid's knife, suit up, and
 * find the laser -- the opening arc of the real game -- without a save file.
 *
 * SCOPE (documented, intentional): only rooms 1..27 of 275 are present; the
 * island/ocean/space half of the map, the day<->night cycle, fuel/flight,
 * scoring, saved games (-r) and the dozens of special-case puzzle verbs
 * (launch/land/dig/swim/drive/ride/light/...) are not ported. Movement is
 * absolute compass rather than facing-relative. No score/log files are ever
 * written (the upstream score-file open is dropped); $BASH_BSDGAMES_STATE_ROOT
 * is honored only as a courtesy in --selftest and no file is created.
 *
 * INTERACTIVE vs HEADLESS. When stdin is a TTY (isatty(0)) the game prints the
 * upstream banner + first room and then loops reading commands at the ">-: "
 * prompt, like upstream. For tests there is a deterministic headless path: no
 * prompt is printed when stdin is not a TTY, commands are read one line at a
 * time from stdin, and the game stops cleanly at EOF (as upstream's getcom()
 * does via die()). There is no randomness in the ported core, so output is
 * stable without a seed; a `--seed N` flag is accepted for contract uniformity
 * and seeds a private PRNG that the combat stub *could* use.
 *
 * COMMANDS (one verb phrase per line; case-insensitive words):
 *   n s e w u d / north south east west up down   -- move
 *   look | lo                                     -- redescribe the room
 *   take|get OBJ [and OBJ...] | take everything    -- pick objects up
 *   drop OBJ [and OBJ...] | drop everything         -- put objects down
 *   inven | i                                       -- list what you hold
 *   kill|fight|attack|smite [OBJ]                   -- combat stub
 *   score | time                                    -- status line
 *   quit | q                                         -- leave
 *
 * OPTIONS:
 *   --look | --start  print the opening banner + first room, then exit 0
 *   --rooms           list the ported room graph (debug), exit 0
 *   --seed N          seed the (combat-only) PRNG; default time^pid
 *   --selftest        run internal graph/parser checks, print one line, exit 0
 *   --help            print usage to stdout, exit 0
 */

#define BG_BATTLESTAR_NROOMS   27        /* ported subset of the 275-room map   */
#define BG_BATTLESTAR_START    22        /* upstream starting position          */
#define BG_BATTLESTAR_LINELEN  256
#define BG_BATTLESTAR_NWORD    20
#define BG_BATTLESTAR_WORDLEN  16
#define BG_BATTLESTAR_MAXWEIGHT 60
#define BG_BATTLESTAR_MAXCUMBER 10

/* word "types" (article field in the upstream wlist[]) */
#define BG_BATTLESTAR_VERB   0
#define BG_BATTLESTAR_OBJECT 1
#define BG_BATTLESTAR_NOUNS  2
#define BG_BATTLESTAR_PREPS  3
