typedef struct {
    bg_monop_player play[BG_MONOP_NPLAY];
    int  cur;               /* current player index                          */
    int  num_doub;          /* doubles rolled this turn                      */
    int  interactive;       /* prompt only when stdin is a TTY               */
    int  over;              /* game finished                                 */
    int  card_idx;          /* rotating index into the small card set        */
} bg_monop_game;

/* ---- board setup --------------------------------------------------------- */
static void bg_monop_init_board (void) {
    int i;
    for (i = 0; i <= BG_MONOP_NSQRS; i++) {
        bg_monop_board[i].name   = bg_monop_tmpl[i].name;
        bg_monop_board[i].type   = bg_monop_tmpl[i].type;
        bg_monop_board[i].cost   = bg_monop_tmpl[i].cost;
        bg_monop_board[i].owner  = -1;
        bg_monop_board[i].prop   = -1;
        bg_monop_board[i].houses = 0;
        bg_monop_board[i].monop  = 0;
    }
    for (i = 0; i < BG_MONOP_NPROP; i++)
        bg_monop_board[bg_monop_props[i].square].prop = (short) i;
}

/* Recompute railroad / utility counts and monopoly flags for player `pl`. */
static void bg_monop_recompute (bg_monop_game *g, int pl) {
    int s, m, mi;
    int rr = 0, ut = 0;

    for (s = 0; s < BG_MONOP_NSQRS; s++) {
        if (bg_monop_board[s].owner != pl)
            continue;
        if (bg_monop_board[s].type == BG_MONOP_RR)   rr++;
        if (bg_monop_board[s].type == BG_MONOP_UTIL) ut++;
    }
    g->play[pl].num_rr   = (short) rr;
    g->play[pl].num_util = (short) ut;

    /* monopoly flags: a group is a monopoly if one owner holds every square */
    for (m = 0; m < BG_MONOP_NMON; m++) {
        int owner = -2, count = 0, total = 0;
        for (s = 0; s < BG_MONOP_NSQRS; s++) {
            if (bg_monop_board[s].prop < 0)
                continue;
            if (bg_monop_props[bg_monop_board[s].prop].mon != m)
                continue;
            total++;
            if (owner == -2)
                owner = bg_monop_board[s].owner;
            if (bg_monop_board[s].owner == owner && owner >= 0)
                count++;
        }
        mi = (count == bg_monop_mons[m].num_in && total == bg_monop_mons[m].num_in
              && owner >= 0);
        for (s = 0; s < BG_MONOP_NSQRS; s++) {
            if (bg_monop_board[s].prop >= 0 &&
                bg_monop_props[bg_monop_board[s].prop].mon == m)
                bg_monop_board[s].monop = (char) mi;
        }
    }
}

/* total worth: cash + costs of owned squares + house investment */
static int bg_monop_worth (bg_monop_game *g, int pl) {
    int s, w = g->play[pl].money;
    for (s = 0; s < BG_MONOP_NSQRS; s++) {
        if (bg_monop_board[s].owner != pl)
            continue;
        w += bg_monop_board[s].cost;
        if (bg_monop_board[s].prop >= 0 && bg_monop_board[s].houses) {
            int m = bg_monop_props[bg_monop_board[s].prop].mon;
            w += bg_monop_mons[m].h_cost * 50 * bg_monop_board[s].houses;
        }
    }
    return w;
}

/* ---- output -------------------------------------------------------------- */
static void bg_monop_printsq (int sqn) {
    bg_monop_sq *sp = &bg_monop_board[sqn];
    printf ("%-18.18s", sp->name);
    switch (sp->type) {
      case BG_MONOP_PRPTY: {
        bg_monop_prop *pp = &bg_monop_props[sp->prop];
        if (sp->owner < 0)
            printf (" -  %-8.8s %4d", bg_monop_mons[pp->mon].name, sp->cost);
        else
            printf (" %d  %-8.8s %4d", sp->owner + 1,
                    bg_monop_mons[pp->mon].name, sp->cost);
        break;
      }
      case BG_MONOP_RR:
        if (sp->owner < 0) printf (" -  Railroad  %4d", sp->cost);
        else               printf (" %d  Railroad  %4d", sp->owner + 1, sp->cost);
        break;
      case BG_MONOP_UTIL:
        if (sp->owner < 0) printf (" -  Utility   %4d", sp->cost);
        else               printf (" %d  Utility   %4d", sp->owner + 1, sp->cost);
        break;
      default:
        break;
    }
    putchar ('\n');
}

static void bg_monop_printboard (void) {
    int i;
    printf ("Square            Own Group     Cost\n");
    for (i = 0; i < BG_MONOP_NSQRS; i++)
        bg_monop_printsq (i);
}

static void bg_monop_where (bg_monop_game *g) {
    int i;
    for (i = 0; i < BG_MONOP_NPLAY; i++) {
        if (g->play[i].bankrupt) {
            printf ("%s (%d) is bankrupt\n", g->play[i].name, i + 1);
            continue;
        }
        if (g->play[i].loc == BG_MONOP_JAIL)
            printf ("%s (%d) is in JAIL%s\n", g->play[i].name, i + 1,
                    (i == g->cur) ? " *" : "");
        else
            printf ("%s (%d) on %s%s\n", g->play[i].name, i + 1,
                    bg_monop_board[g->play[i].loc].name,
                    (i == g->cur) ? " *" : "");
    }
}

static void bg_monop_holdings (bg_monop_game *g, int pl) {
    int s, any = 0;
    bg_monop_player *pp = &g->play[pl];
    printf ("%s's (%d) holdings (total worth: $%d):\n", pp->name, pl + 1,
            bg_monop_worth (g, pl));
    printf ("\t$%d cash", pp->money);
    if (pp->num_gojf)
        printf (", %d get-out-of-jail-free", pp->num_gojf);
    putchar ('\n');
    for (s = 0; s < BG_MONOP_NSQRS; s++) {
        if (bg_monop_board[s].owner != pl)
            continue;
        if (!any) { any = 1; }
        putchar ('\t');
        bg_monop_printsq (s);
    }
    if (!any)
        printf ("\t(no property)\n");
}

/* ---- bankruptcy / win ---------------------------------------------------- */
/* Charge `amt` to player pl, paying it to creditor (or the bank if <0).
 * If the player cannot cover it, they go bankrupt and their property reverts. */
static void bg_monop_charge (bg_monop_game *g, int pl, int amt, int creditor) {
    g->play[pl].money -= amt;
    if (creditor >= 0)
        g->play[creditor].money += amt;
    if (g->play[pl].money < 0) {
        int s;
        printf ("%s (%d) cannot pay $%d and is BANKRUPT!\n",
                g->play[pl].name, pl + 1, -g->play[pl].money);
        g->play[pl].bankrupt = 1;
        for (s = 0; s < BG_MONOP_NSQRS; s++)
            if (bg_monop_board[s].owner == pl) {
                bg_monop_board[s].owner  = -1;
                bg_monop_board[s].houses = 0;
            }
        bg_monop_recompute (g, pl);
    }
}

static int bg_monop_count_live (bg_monop_game *g) {
    int i, n = 0;
    for (i = 0; i < BG_MONOP_NPLAY; i++)
        if (!g->play[i].bankrupt)
            n++;
    return n;
}

/* ---- rent ---------------------------------------------------------------- */
static void bg_monop_pay_rent (bg_monop_game *g, int sqn) {
    bg_monop_sq *sp = &bg_monop_board[sqn];
    int owner = sp->owner;
    int rnt = 0;

    printf ("Owned by %s\n", g->play[owner].name);
    switch (sp->type) {
      case BG_MONOP_PRPTY: {
        bg_monop_prop *pp = &bg_monop_props[sp->prop];
        if (sp->monop) {
            if (sp->houses == 0)
                printf ("rent is %d\n", rnt = pp->rent[0] * 2);
            else if (sp->houses < 5)
                printf ("with %d houses, rent is %d\n", sp->houses,
                        rnt = pp->rent[sp->houses]);
            else
                printf ("with a hotel, rent is %d\n", rnt = pp->rent[5]);
        } else
            printf ("rent is %d\n", rnt = pp->rent[0]);
        break;
      }
      case BG_MONOP_RR:
        rnt = 25 << (g->play[owner].num_rr - 1);
        printf ("rent is %d\n", rnt);
        break;
      case BG_MONOP_UTIL: {
        int r = bg_monop_die () + bg_monop_die ();
        if (g->play[owner].num_util == 2) {
            printf ("rent is 10 * roll (%d) = %d\n", r, r * 10);
            rnt = r * 10;
        } else {
            printf ("rent is 4 * roll (%d) = %d\n", r, r * 4);
            rnt = r * 4;
        }
        break;
      }
    }
    bg_monop_charge (g, g->cur, rnt, owner);
}

/* ---- buying -------------------------------------------------------------- */
static void bg_monop_buy (bg_monop_game *g, int pl, int sqn) {
    printf ("%s (%d) buys %s for $%d\n", g->play[pl].name, pl + 1,
            bg_monop_board[sqn].name, bg_monop_board[sqn].cost);
    bg_monop_board[sqn].owner = (short) pl;
    bg_monop_charge (g, pl, bg_monop_board[sqn].cost, -1);
    bg_monop_recompute (g, pl);
}

/* ---- small deterministic card set (a stand-in for the full decks) -------- */
/* Each card is a small effect chosen by a rotating index so headless runs are
 * reproducible. Faithful decks (16+16 cards) are out of scope for this core. */
static void bg_monop_draw_card (bg_monop_game *g, int chance) {
    static const struct { const char *msg; int delta; int gojf; int gojail; }
        deck[] = {
        { "Bank pays you a dividend of $50",            50,  0, 0 },
        { "Pay poor tax of $15",                       -15,  0, 0 },
        { "GET OUT OF JAIL FREE",                        0,  1, 0 },
        { "Go directly to JAIL",                         0,  0, 1 },
        { "You inherit $100",                          100,  0, 0 },
        { "Doctor's fees -- pay $50",                  -50,  0, 0 }
    };
    int n = (int) (sizeof deck / sizeof deck[0]);
    int idx = g->card_idx % n;
    g->card_idx++;
    printf ("%s card: %s\n", chance ? "Chance" : "Community Chest",
            deck[idx].msg);
    if (deck[idx].gojf) {
        g->play[g->cur].num_gojf++;
    } else if (deck[idx].gojail) {
        g->play[g->cur].loc = BG_MONOP_JAIL;
        g->play[g->cur].in_jail = 0;
    } else if (deck[idx].delta) {
        bg_monop_charge (g, g->cur, -deck[idx].delta, -1);
    }
}

/* ---- special squares (taxes / go-to-jail) -------------------------------- */
static void bg_monop_inc_tax (bg_monop_game *g) {
    int worth = bg_monop_worth (g, g->cur);
    int ten = worth / 10;
    int pay = (ten < 200) ? ten : 200;     /* pay the lesser (simple policy) */
    printf ("Income Tax: you were worth $%d, you pay $%d\n", worth, pay);
    bg_monop_charge (g, g->cur, pay, -1);
}

static void bg_monop_lux_tax (bg_monop_game *g) {
    printf ("Luxury Tax: you lose $75\n");
    bg_monop_charge (g, g->cur, 75, -1);
}

/* ---- landing logic ------------------------------------------------------- */
/* Decide whether player pl will buy the unowned square at `loc`.
 * Headless human reads a yes/no line; computer uses an affordability rule. */
static int bg_monop_decide_buy (bg_monop_game *g, int pl, int loc, FILE *in) {
    bg_monop_sq *sp = &bg_monop_board[loc];

    if (g->play[pl].is_comp) {
        /* Buy if it leaves a reasonable cash cushion. Deterministic. */
        int keep = 100;
        int yes = (g->play[pl].money - sp->cost >= keep);
        printf ("%s (%d) %s buy %s ($%d)\n", g->play[pl].name, pl + 1,
                yes ? "decides to" : "declines to", sp->name, sp->cost);
        return yes;
    }

    printf ("That would cost $%d\n", sp->cost);
    for (;;) {
        char buf[128];
        size_t len;
        if (g->interactive) {
            fputs ("Do you want to buy? ", stdout);
            fflush (stdout);
        }
        if (!fgets (buf, sizeof buf, in))
            return -1;                      /* EOF */
        len = strlen (buf);
        while (len && (buf[len - 1] == '\n' || buf[len - 1] == '\r'))
            buf[--len] = '\0';
        if (buf[0] == 'y' || buf[0] == 'Y') {
            if (g->play[pl].money < sp->cost) {
                printf ("You can't afford that ($%d cash)\n", g->play[pl].money);
                return 0;
            }
            return 1;
        }
        if (buf[0] == 'n' || buf[0] == 'N' || buf[0] == '\0')
            return 0;
        printf ("Please answer yes or no\n");
    }
}

/* Resolve the square the current player has landed on. Returns -1 on EOF. */
static int bg_monop_land (bg_monop_game *g, FILE *in) {
    int loc = g->play[g->cur].loc;
    bg_monop_sq *sp = &bg_monop_board[loc];

    printf ("That puts you on %s\n", sp->name);
    switch (sp->type) {
      case BG_MONOP_SAFE:
        printf ("That is a safe place\n");
        break;
      case BG_MONOP_CC:
        bg_monop_draw_card (g, 0);
        break;
      case BG_MONOP_CHANCE:
        bg_monop_draw_card (g, 1);
        break;
      case BG_MONOP_INC_TAX:
        bg_monop_inc_tax (g);
        break;
      case BG_MONOP_LUX_TAX:
        bg_monop_lux_tax (g);
        break;
      case BG_MONOP_GOTO_J:
        printf ("Go directly to JAIL\n");
        g->play[g->cur].loc = BG_MONOP_JAIL;
        g->play[g->cur].in_jail = 0;
        break;
      case BG_MONOP_PRPTY:
      case BG_MONOP_RR:
      case BG_MONOP_UTIL:
        if (sp->owner < 0) {
            int d = bg_monop_decide_buy (g, g->cur, loc, in);
            if (d < 0)
                return -1;
            if (d)
                bg_monop_buy (g, g->cur, loc);
            else
                printf ("It stays unowned for now\n");
        } else if (sp->owner == g->cur) {
            printf ("You own it.\n");
        } else {
            bg_monop_pay_rent (g, loc);
        }
        break;
    }
    return 0;
}

/* ---- movement ------------------------------------------------------------ */
static void bg_monop_move (bg_monop_game *g, int rl) {
    int old = g->play[g->cur].loc;
    g->play[g->cur].loc = (old + rl) % BG_MONOP_NSQRS;
    if (g->play[g->cur].loc < old && rl > 0) {
        g->play[g->cur].money += 200;
        printf ("You pass %s and get $200\n", bg_monop_board[0].name);
    }
}

/* A jail turn (jail.c move_jail). Returns 1 if the player got out (and moved),
 * 0 if they remain in jail (turn ends). */
static int bg_monop_move_jail (bg_monop_game *g, int r1, int r2) {
    bg_monop_player *pp = &g->play[g->cur];
    if (r1 != r2) {
        printf ("Sorry, that doesn't get you out\n");
        if (++pp->in_jail == 3) {
            printf ("Third turn, no doubles -- you pay $50\n");
            bg_monop_charge (g, g->cur, 50, -1);
            pp->loc = 10;
            pp->in_jail = 0;
            bg_monop_move (g, r1 + r2);
            return 1;
        }
        return 0;
    }
    printf ("Double roll gets you out.\n");
    pp->loc = 10;
    pp->in_jail = 0;
    bg_monop_move (g, r1 + r2);
    return 1;
}

/* Execute one roll for the current player. Returns 1 if the turn ends, 0 if the
 * player rolled doubles and goes again, -1 on EOF (during a buy prompt). */
static int bg_monop_do_roll (bg_monop_game *g, FILE *in) {
    int r1 = bg_monop_die ();
    int r2 = bg_monop_die ();
    int was_jail = 0;

    printf ("roll is %d, %d\n", r1, r2);
    if (g->play[g->cur].loc == BG_MONOP_JAIL) {
        was_jail = 1;
        if (!bg_monop_move_jail (g, r1, r2))
            return 1;                       /* still in jail; turn ends */
    } else {
        if (r1 == r2 && ++g->num_doub == 3) {
            printf ("That's 3 doubles.  You go to jail\n");
            g->play[g->cur].loc = BG_MONOP_JAIL;
            g->play[g->cur].in_jail = 0;
            return 1;
        }
        bg_monop_move (g, r1 + r2);
    }
    if (bg_monop_land (g, in) < 0)
        return -1;
    if (g->play[g->cur].bankrupt)
        return 1;
    /* doubles go again (but not after escaping jail) */
    if (r1 == r2 && !was_jail)
        return 0;
    return 1;
}

/* ---- computer turn ------------------------------------------------------- */
static void bg_monop_comp_turn (bg_monop_game *g) {
    bg_monop_player *pp = &g->play[g->cur];
    int guard = 0;

    printf ("\n%s (%d) (cash $%d) on %s\n", pp->name, g->cur + 1, pp->money,
            (pp->loc == BG_MONOP_JAIL) ? "JAIL" : bg_monop_board[pp->loc].name);

    /* Computer in jail pays out immediately if it can afford it. */
    if (pp->loc == BG_MONOP_JAIL && pp->money > 100) {
        printf ("%s pays $50 to leave jail\n", pp->name);
        bg_monop_charge (g, g->cur, 50, -1);
        pp->loc = 10;
        pp->in_jail = 0;
    }

    for (;;) {
        int r = bg_monop_do_roll (g, NULL);   /* NULL stdin: never prompts */
        if (r != 0)                           /* turn ended or bankrupt    */
            break;
        printf ("%s rolled doubles.  Goes again\n", pp->name);
        if (++guard > 10)                     /* safety: never loop forever */
            break;
    }
    g->num_doub = 0;
}

/* ---- command grammar (unique-prefix match, like getinp.c) ---------------- */
static const char *const bg_monop_comlist[] = {
    "quit", "print", "where", "own holdings", "holdings",
    "pay", "card", "roll", "?", NULL
};
enum { BG_C_QUIT, BG_C_PRINT, BG_C_WHERE, BG_C_OWNHOLD, BG_C_HOLD,
       BG_C_PAY, BG_C_CARD, BG_C_ROLL, BG_C_HELP };

/* Return the command index for a (lowercased, space-collapsed) line, or -1 for
 * no/ambiguous match. A bare empty line means "roll". */
static int bg_monop_match (const char *line) {
    int i, n_match = 0, match = -1;
    if (line[0] == '\0')
        return BG_C_ROLL;
    for (i = 0; bg_monop_comlist[i]; i++) {
        const char *a = line, *b = bg_monop_comlist[i];
        while (*a && *b && *a == *b) { a++; b++; }
        if (*a == '\0') {               /* line is a prefix of command i */
            n_match++;
            match = i;
        }
    }
    if (n_match == 1)
        return match;
    return -1;
}

static void bg_monop_help (void) {
    int i;
    printf ("Valid commands are: ");
    for (i = 0; bg_monop_comlist[i]; i++) {
        printf ("%s", bg_monop_comlist[i]);
        if (bg_monop_comlist[i + 1])
            printf (", ");
    }
    putchar ('\n');
}

/* ---- main play loop ------------------------------------------------------ */
static void bg_monop_jail_pay (bg_monop_game *g) {
    bg_monop_player *pp = &g->play[g->cur];
    if (pp->loc != BG_MONOP_JAIL) {
        printf ("But you're not IN Jail\n");
        return;
    }
    pp->loc = 10;
    pp->in_jail = 0;
    printf ("That cost you $50\n");
    bg_monop_charge (g, g->cur, 50, -1);
}

static void bg_monop_jail_card (bg_monop_game *g) {
    bg_monop_player *pp = &g->play[g->cur];
    if (pp->loc != BG_MONOP_JAIL) {
        printf ("But you're not IN Jail\n");
        return;
    }
    if (pp->num_gojf == 0) {
        printf ("But you don't HAVE a get out of jail free card\n");
        return;
    }
    pp->num_gojf--;
    pp->loc = 10;
    pp->in_jail = 0;
    printf ("You use a get-out-of-jail-free card\n");
}

/* Announce the start of the human's turn. */
static void bg_monop_announce (bg_monop_game *g) {
    bg_monop_player *pp = &g->play[g->cur];
    printf ("\n%s (%d) (cash $%d) on %s\n", pp->name, g->cur + 1, pp->money,
            (pp->loc == BG_MONOP_JAIL) ? "JAIL" : bg_monop_board[pp->loc].name);
    if (pp->loc == BG_MONOP_JAIL)
        printf ("(This is turn %d in JAIL)\n", pp->in_jail + 1);
}

static int bg_monop_play (bg_monop_game *g, FILE *in) {
    char buf[256];

    bg_monop_announce (g);
    if (g->interactive) {
        fputs ("-- Command: ", stdout);
        fflush (stdout);
    }

    while (fgets (buf, sizeof buf, in)) {
        size_t len = strlen (buf);
        char *p;
        int cmd;

        while (len && (buf[len - 1] == '\n' || buf[len - 1] == '\r'))
            buf[--len] = '\0';
        /* lowercase + collapse leading spaces (getinp.c semantics, simplified) */
        for (p = buf; *p; p++)
            *p = (char) tolower ((unsigned char) *p);
        while (buf[0] == ' ')
            memmove (buf, buf + 1, strlen (buf));

        cmd = bg_monop_match (buf);
        if (cmd < 0) {
            if (buf[0] != '\0')
                printf ("Illegal command: \"%s\".  Use '?' for the list\n", buf);
        } else switch (cmd) {
          case BG_C_QUIT:
            printf ("Thanks for playing\n");
            g->over = 1;
            return 0;
          case BG_C_PRINT:
            bg_monop_printboard ();
            break;
          case BG_C_WHERE:
            bg_monop_where (g);
            break;
          case BG_C_OWNHOLD:
          case BG_C_HOLD:
            bg_monop_holdings (g, g->cur);
            break;
          case BG_C_HELP:
            bg_monop_help ();
            break;
          case BG_C_PAY:
            bg_monop_jail_pay (g);
            break;
          case BG_C_CARD:
            bg_monop_jail_card (g);
            break;
          case BG_C_ROLL: {
            int r = bg_monop_do_roll (g, in);
            if (r < 0)
                return 0;                   /* EOF mid-buy: stop cleanly */
            if (r == 0) {
                printf ("%s rolled doubles.  Goes again\n",
                        g->play[g->cur].name);
                break;                      /* same player rolls again */
            }
            /* human turn ended: let the computer(s) take their turns */
            g->num_doub = 0;
            if (g->play[g->cur].bankrupt || bg_monop_count_live (g) <= 1) {
                /* fall through to end-of-game check below */
            } else {
                int next = g->cur;
                int safety = 0;
                do {
                    next = (next + 1) % BG_MONOP_NPLAY;
                    if (g->play[next].bankrupt)
                        continue;
                    g->cur = next;
                    if (g->play[next].is_comp) {
                        bg_monop_comp_turn (g);
                    } else {
                        break;              /* back to a human */
                    }
                } while (g->play[next].is_comp && ++safety < BG_MONOP_NPLAY + 1);
                g->cur = next;
            }

            if (bg_monop_count_live (g) <= 1) {
                int i;
                for (i = 0; i < BG_MONOP_NPLAY; i++)
                    if (!g->play[i].bankrupt) {
                        printf ("\n%s (%d) wins!\n", g->play[i].name, i + 1);
                        break;
                    }
                g->over = 1;
                return 0;
            }
            bg_monop_announce (g);
            break;
          }
        }

        if (g->interactive) {
            fputs ("-- Command: ", stdout);
            fflush (stdout);
        }
    }
    return 0;                               /* EOF: stop cleanly */
}

/* ---- usage / selftest ---------------------------------------------------- */
static int bg_monop_usage (FILE *fp, int rc) {
    fputs ("usage: monop [--seed N] [--no-score]\n"
           "       monop --selftest\n"
           "stdin (headless): one command per line --\n"
           "  roll (or <RETURN>), print, where, holdings, pay, card, quit, ?\n",
           fp);
    return rc;
}

static int bg_monop_selftest (void) {
    int fail = 0, i, s;
    bg_monop_game g;

    bg_monop_seed (1);
    bg_monop_init_board ();

    /* board sanity */
    if (strcmp (bg_monop_board[0].name, "=== GO ===") != 0) fail++;
    if (bg_monop_board[BG_MONOP_JAIL].type != BG_MONOP_IN_JAIL) fail++;
    if (strcmp (bg_monop_board[39].name, "Boardwalk") != 0) fail++;
    if (bg_monop_board[39].cost != 400) fail++;
    if (bg_monop_board[5].type != BG_MONOP_RR) fail++;

    /* every property square resolves to a prop entry with the right group */
    for (i = 0; i < BG_MONOP_NPROP; i++) {
        s = bg_monop_props[i].square;
        if (bg_monop_board[s].type != BG_MONOP_PRPTY) fail++;
        if (bg_monop_board[s].prop != i) fail++;
    }

    /* die is always in 1..6 */
    for (i = 0; i < 1000; i++) {
        int d = bg_monop_die ();
        if (d < 1 || d > 6) fail++;
    }

    /* monopoly detection: give player 0 both PURPLE squares (1,3) */
    bg_monop_init_board ();
    memset (&g, 0, sizeof g);
    bg_monop_board[1].owner = 0;
    bg_monop_board[3].owner = 0;
    bg_monop_recompute (&g, 0);
    if (!bg_monop_board[1].monop || !bg_monop_board[3].monop) fail++;
    /* give only one -> not a monopoly */
    bg_monop_init_board ();
    bg_monop_board[1].owner = 0;
    bg_monop_recompute (&g, 0);
    if (bg_monop_board[1].monop) fail++;

    /* railroad rent doubling: 1 RR => 25, 2 RR => 50 */
    bg_monop_init_board ();
    bg_monop_board[5].owner = 0;
    bg_monop_recompute (&g, 0);
    if (g.play[0].num_rr != 1) fail++;
    bg_monop_board[15].owner = 0;
    bg_monop_recompute (&g, 0);
    if (g.play[0].num_rr != 2) fail++;
    if ((25 << (g.play[0].num_rr - 1)) != 50) fail++;

    /* command prefix matcher */
    if (bg_monop_match ("ro") != BG_C_ROLL) fail++;
    if (bg_monop_match ("") != BG_C_ROLL) fail++;
    if (bg_monop_match ("q") != BG_C_QUIT) fail++;
    if (bg_monop_match ("xyzzy") != -1) fail++;

    /* worth: cash + property cost */
    bg_monop_init_board ();
    memset (&g, 0, sizeof g);
    g.play[0].money = 1500;
    bg_monop_board[39].owner = 0;     /* Boardwalk, cost 400 */
    if (bg_monop_worth (&g, 0) != 1900) fail++;

    printf ("monop selftest %s\n", fail == 0 ? "ok" : "FAIL");
    return fail == 0 ? 0 : 1;
}

/* ---- adapter entry ------------------------------------------------------- */
static int bsdg_monop (int argc, char **argv) {
    bg_monop_game g;
    int i, seeded = 0;
    uint64_t seed = 0;
    const char *env;

    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp (a, "--help") == 0 || strcmp (a, "-h") == 0)
            return bg_monop_usage (stdout, 0);
        if (strcmp (a, "--selftest") == 0)
            return bg_monop_selftest ();
        if (strcmp (a, "--no-score") == 0)
            continue;                       /* default; accepted no-op */
        if (strcmp (a, "--seed") == 0) {
            char *ep;
            if (i + 1 >= argc) {
                fputs ("monop: --seed requires an argument\n", stderr);
                return bg_monop_usage (stderr, 2);
            }
            seed = (uint64_t) strtoull (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i])
                return bg_monop_usage (stderr, 2);
            seeded = 1;
            continue;
        }
        return bg_monop_usage (stderr, 2);
    }

    /* seed precedence: --seed N > $BASH_BSDGAMES_SEED > time^pid */
    if (!seeded && (env = getenv ("BASH_BSDGAMES_SEED")) != NULL && *env) {
        char *ep;
        uint64_t v = (uint64_t) strtoull (env, &ep, 10);
        if (*ep == '\0' && ep != env) {
            seed = v;
            seeded = 1;
        }
    }
    if (seeded)
        bg_monop_seed (seed);
    else
        bg_monop_seed ((uint64_t) time (NULL) ^ (uint64_t) getpid ());

    bg_monop_init_board ();
    memset (&g, 0, sizeof g);
    g.cur = 0;
    g.interactive = isatty (0) ? 1 : 0;
    g.play[0].name    = "Player";
    g.play[0].money   = BG_MONOP_START;
    g.play[0].loc     = 0;
    g.play[0].is_comp = 0;
    g.play[1].name    = "Computer";
    g.play[1].money   = BG_MONOP_START;
    g.play[1].loc     = 0;
    g.play[1].is_comp = 1;

    if (g.interactive) {
        printf ("Monopoly: you (Player 1) vs the Computer (Player 2).\n");
        printf ("Each starts with $%d.  Type ? for commands.\n", BG_MONOP_START);
    }

    return bg_monop_play (&g, stdin);
}

/* ===== phantasia.c ===== */
/* @game phantasia : fantasy RPG -- roll a character, roam the plane, fight monsters, gain levels */
/* bsdgames `phantasia`: an interactive, originally-multiplayer fantasy
 * role-playing game.  You roll up a character of one of seven types, wander a
 * 2-D coordinate "plane" (the Phantasia universe), bump into monsters that
 * scale with how far out from the origin you have travelled, fight them with
 * weapon and spell, earn experience, and climb levels.  The historical game is
 * enormous and built around a set of SHARED on-disk state files (a player
 * ledger, a monster database compiled from `monsters.asc`, an energy-void
 * file, a scoreboard, a gold/lastdate file, an inter-terminal message file).
 *
 * SCOPE (bounded but genuinely playable single-player core).  This adapter is
 * a fresh C rewrite of the single-player heart of the engine, deliberately
 * self-contained and STATELESS: it never opens, reads, or writes any of those
 * shared files by default, so there is no multiplayer ledger, no persistent
 * world, and tests create nothing on disk.  What is faithfully reproduced from
 * the NetBSD sources (phantglobs.c Stattable/nametable, main.c genchar/
 * initplayer/movelevel, misc.c explevel/descrlocation/distance, fight.c
 * encounter/callmonster/playerhits/monsthits/hitmonster):
 *   - character roll: the real 7-row Stattable, ROLL(base, interval) per stat;
 *   - the coordinate plane: CIRCLE(x,y)=floor(dist/125+1), the region-name
 *     table by circle threshold and quadrant, MAXMOVE()=level*1.5+1;
 *   - movement (h/j/k/l == w/s/n/e), resting (recovers energy/mana, may spawn a
 *     wandering monster), and a 0.2-per-rest wandering-encounter chance;
 *   - monster encounters: a representative embedded monster table (a subset of
 *     monsters.asc spanning weak fae through the Dark Lord), scaled by Circle
 *     exactly as callmonster() does, the speed race that decides who strikes,
 *     and the player combat menu Melee / Skirmish / Nick / Evade / Spell(bolt);
 *   - experience and leveling: explevel(exp)=floor(pow(exp/1000,0.4875)) and
 *     movelevel()'s per-stat increase*inc; reaching level 3000 makes you a
 *     member of the Council of the Wise (a "win"); death ends the game.
 * DELIBERATELY OMITTED (documented): trading posts, the king/valar/wizard
 * special roles and council/king politics, rings, the holy-grail search, the
 * energy void, inter-terminal battle, scoreboard persistence, and the dozens of
 * SM_* special-monster side effects beyond the common-case hit.  A `--no-score`
 * flag is accepted (and is a no-op, since no score is ever written); if score
 * writing were added it would be opt-in and honor BASH_BSDGAMES_STATE_ROOT.
 *
 * INTERACTIVE vs HEADLESS.  When stdin is a TTY (isatty(0)) the game prints a
 * status line and a "-> " prompt before each command and offers a character-
 * type menu at the start.  For tests there is a deterministic headless path: a
 * private xorshift64* PRNG (pinned by `--seed N` or $BASH_BSDGAMES_SEED) drives
 * the character roll and every monster/encounter "die roll", commands are read
 * one line at a time from stdin, no prompts are emitted, and the game stops
 * cleanly at EOF (or after a bounded turn cap so it can never loop forever).
 *
 * COMMANDS (one per line; first letter, case-insensitive):
 *   n  north (up,  +y)            s  south (down, -y)
 *   e  east  (right,+x)           w  west  (left, -x)
 *   h/j/k/l  vi-style w/s/n/e (matches upstream HJKL)
 *   r  rest (recover energy/mana; may trigger a wandering monster)
 *   x  examine: print full character stats
 *   m [N]  force a monster encounter (optional monster index N)
 *   1..5   in an encounter: Melee / Skirmish / Evade / Magic bolt / Nick
 *          (also usable as the default action selector; see below)
 *   q      quit (leave the plane)
 *   (blank) no-op
 * During an encounter the same line-reader is used: send 1/2/3/4/5 to choose
 * Melee/Skirmish/Evade/Spell/Nick.  If a fight is in progress and a movement
 * command arrives, it is treated as "Melee" so a scripted test never deadlocks.
 *
 * OPTIONS:
 *   --char N | -c N   pick character type 1..7 (1=Magic 2=Fighter 3=Elf
 *                     4=Dwarf 5=Halfling 6=Experimento 7=Super); default 2.
 *   --seed N          pin the PRNG (default: time^pid; tests pass this).
 *   --no-score        accepted no-op (this build never writes score files).
 *   --stats           roll the chosen character, print its stat block, exit 0.
 *   --selftest        run internal checks, print one stable line, exit 0.
 *   --help            print usage to stdout, exit 0.
 *
 * Adapter spliced into bsdgames.c (which provides the includes); all
 * symbols are static and bg_phantasia_-prefixed.  No curses, no state files,
 * no terminal raw mode. */

/* ---- constants (mirror phantdefs.h / macros.h where relevant) ------------ */
