#define BG_PHANT_OLDAGE_LEVEL  9999.0/* level past which old age kills you   */
#define BG_PHANT_MAXTURNS      100000/* hard cap on headless turns (safety)  */

/* one embedded monster record (a subset of monsters.asc).  Columns mirror the
 * ascii file: name, strength, brains, speed, energy, experience, flock%.  The
 * treasure/special-type columns are not needed for the bounded combat core. */
typedef struct {
    const char *name;
    double strength;
    double brains;
    double speed;
    double energy;
    double experience;
    double flock;       /* percent chance of flocking */
} bg_phantasia_mrec;

