/* ---- player state -------------------------------------------------------- */
typedef struct {
    double experience, level;
    double strength, might;            /* might == effective strength */
    double energy, maxenergy, shield;
    double quickness, speed;           /* speed == effective quickness */
    double magiclvl, mana, brains;
    double gold, x, y;
    int    type;
    int    interactive;
    int    alive;
    int    council;                    /* reached the Council (win) */
} bg_phantasia_player;

/* current-monster working copy during a fight */
typedef struct {
    char   name[32];
    double strength, brains, speed, energy, experience, flock;
    double o_strength, o_speed, o_energy, maxspeed;
    double melee, skirmish;
    int    active;
} bg_phantasia_curmon;

/* ---- private seeded PRNG (xorshift64*) ----------------------------------- */
static uint64_t bg_phantasia_state = 0x9e3779b97f4a7c15ULL;

static void bg_phantasia_seed (uint64_t s) {
    s ^= 0x9e3779b97f4a7c15ULL;
    s = (s ^ (s >> 30)) * 0xbf58476d1ce4e5b9ULL;
    s = (s ^ (s >> 27)) * 0x94d049bb133111ebULL;
    s ^= s >> 31;
    if (s == 0)
        s = 0x9e3779b97f4a7c15ULL;
    bg_phantasia_state = s;
}

static uint64_t bg_phantasia_next (void) {
    uint64_t x = bg_phantasia_state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    bg_phantasia_state = x;
    return x;
}

/* drandom(): a double in [0,1), the upstream RNG primitive (random()&0x7fff)/
 * 32768.0.  We take 15 bits from our PRNG to mirror that resolution. */
static double bg_phantasia_drandom (void) {
    return (double) (bg_phantasia_next () & 0x7fff) / 32768.0;
}

/* ROLL(base, interval) == floor(base + interval*drandom()). */
static double bg_phantasia_roll_macro (double base, double interval) {
    return floor (base + interval * bg_phantasia_drandom ());
}

/* ---- math helpers (mirror macros.h / misc.c) ----------------------------- */
static double bg_phantasia_distance (double x1, double x2, double y1, double y2) {
    double dx = x1 - x2, dy = y1 - y2;
    return sqrt (dx * dx + dy * dy);
}

/* CIRCLE(x,y) == floor(distance(x,0,y,0)/125 + 1). */
static double bg_phantasia_circle (double x, double y) {
    return floor (bg_phantasia_distance (x, 0.0, y, 0.0) / 125.0 + 1.0);
}

/* explevel(exp) == floor(pow(exp/1000, 0.4875)) for exp < 1.1e7. */
static double bg_phantasia_explevel (double experience) {
    if (experience < 1.1e7)
        return floor (pow (experience / 1000.0, 0.4875));
    return floor (pow (experience / 1250.0, 0.4865));
}

/* MAXMOVE() == level*1.5 + 1. */
static double bg_phantasia_maxmove (const bg_phantasia_player *p) {
    return p->level * 1.5 + 1.0;
}

/* descrlocation(): region name for the player's coordinates.  Faithful to
 * misc.c: circle thresholds for the outer wastes, else a quadrant lookup. */
static const char *bg_phantasia_location (double x, double y) {
    static const char *const nametable[4][4] = {
        { "Anorien", "Ithilien", "Rohan", "Lorien" },
        { "Gondor", "Mordor", "Dunland", "Rovanion" },
        { "South Gondor", "Khand", "Eriador", "The Iron Hills" },
        { "Far Harad", "Near Harad", "The Northern Waste", "Rhun" }
    };
    double c = bg_phantasia_circle (x, y);
    int quadrant;
    if (c >= 1000.0) {
        double m = fabs (x) > fabs (y) ? fabs (x) : fabs (y);
        return m > 1.1e6 ? "The Point of No Return" : "The Ashen Mountains";
    }
    if (c >= 55.0) return "Morannon";
    if (c >= 35.0) return "Kennaquahair";
    if (c >= 20.0) return "The Dead Marshes";
    if (c >= 9.0)  return "The Outer Waste";
    if (c >= 5.0)  return "The Moors Adventurous";
    if (x == 0.0 && y == 0.0) return "The Lord's Chamber";
    quadrant = (x > 0.0) ? 1 : 0;
    quadrant += (y >= 0.0) ? 2 : 0;
    return nametable[((int) c) - 1][quadrant];
}

/* ---- character roll (mirror initplayer + genchar) ------------------------ */
static void bg_phantasia_initplayer (bg_phantasia_player *p, int type) {
    const bg_phantasia_cstat *st;

    memset (p, 0, sizeof *p);
    if (type < BG_PHANT_C_MAGIC || type >= BG_PHANT_NTYPES)
        type = BG_PHANT_C_FIGHTER;
    p->type = type;
    p->alive = 1;
    p->council = 0;

    /* initplayer: a little gold and a random starting square. */
    p->gold = bg_phantasia_roll_macro (50.0, 75.0) + 0.1;
    p->x = bg_phantasia_roll_macro (-125.0, 251.0);
    p->y = bg_phantasia_roll_macro (-125.0, 251.0);

    /* genchar: roll each stat from the type's Stattable row. */
    st = &bg_phantasia_stattable[type];
    p->quickness = bg_phantasia_roll_macro (st->quickness.base, st->quickness.interval);
    p->strength  = bg_phantasia_roll_macro (st->strength.base,  st->strength.interval);
    p->mana      = bg_phantasia_roll_macro (st->mana.base,      st->mana.interval);
    p->maxenergy = p->energy =
                   bg_phantasia_roll_macro (st->energy.base,    st->energy.interval);
    p->brains    = bg_phantasia_roll_macro (st->brains.base,    st->brains.interval);
    p->magiclvl  = bg_phantasia_roll_macro (st->magiclvl.base,  st->magiclvl.interval);

    /* halflings start with some experience (and thus a level). */
    if (type == BG_PHANT_C_HALFLING)
        p->experience = bg_phantasia_roll_macro (600.0, 200.0);

    /* adjuststats(): effective strength/quickness; level from experience. */
    p->might = p->strength;
    p->speed = p->quickness;
    p->level = bg_phantasia_explevel (p->experience);
}

/* movelevel(): apply per-stat increases for each new level reached. */
static void bg_phantasia_movelevel (bg_phantasia_player *p) {
    const bg_phantasia_cstat *st = &bg_phantasia_stattable[p->type];
    double newlvl = bg_phantasia_explevel (p->experience);
    double inc = newlvl - p->level;
    if (inc <= 0.0)
        return;
    p->level = newlvl;
    p->strength  += st->strength.increase  * inc;
    p->mana      += st->mana.increase      * inc;
    p->brains    += st->brains.increase    * inc;
    p->magiclvl  += st->magiclvl.increase  * inc;
    p->maxenergy += st->energy.increase    * inc;
    p->energy = p->maxenergy + p->shield;   /* rest to max on level-up */
    p->might = p->strength;
    p->speed = p->quickness;
    if (p->level >= BG_PHANT_COUNCIL_LEVEL && !p->council) {
        p->council = 1;
        printf ("You have made it to the Council of the Wise.\n");
        printf ("Good Luck on your search for the Holy Grail.\n");
    }
    if (p->level > BG_PHANT_OLDAGE_LEVEL && !p->council) {
        printf ("You died of old age.\n");
        p->alive = 0;
    }
}

/* ---- combat (mirror callmonster / playerhits / monsthits / hitmonster) --- */

/* pickmonster(): bounded random index into our embedded table, biased toward
 * deeper (tougher) monsters as the Circle grows -- the spirit of the upstream
 * Marsh/Circle gating without the full water/non-water split. */
static int bg_phantasia_pickmonster (double circle) {
    int n = BG_PHANT_NMONSTERS;
    int span, lo;
    if (circle <= 1.0)
        return (int) bg_phantasia_roll_macro (0.0, (double) (n / 2));
    /* window of candidates centered on the player's depth */
    lo = (int) ((circle - 1.0) * 1.5);
    if (lo < 0) lo = 0;
    if (lo > n - 1) lo = n - 1;
    span = n - lo;
    if (span < 1) span = 1;
    return lo + (int) bg_phantasia_roll_macro (0.0, (double) span);
}

/* callmonster(): copy the record and scale by Circle as upstream does. */
static void bg_phantasia_callmonster (bg_phantasia_curmon *m, int which,
                                      double circle) {
    const bg_phantasia_mrec *src;
    if (which < 0) which = 0;
    if (which >= BG_PHANT_NMONSTERS) which = BG_PHANT_NMONSTERS - 1;
    src = &bg_phantasia_monsters[which];

    memset (m, 0, sizeof *m);
    strncpy (m->name, src->name, sizeof m->name - 1);
    m->name[sizeof m->name - 1] = '\0';
    m->strength   = src->strength;
    m->brains     = src->brains;
    m->speed      = src->speed;
    m->energy     = src->energy;
    m->experience = src->experience;
    m->flock      = src->flock;

    /* adjust stats based on which circle player is in */
    m->strength   *= (1.0 + circle / 2.0);
    m->brains     *= circle;
    m->speed      += circle * 1.0e-9;
    m->energy     *= circle;
    m->experience *= circle;

    m->o_strength = m->strength;
    m->o_speed = m->maxspeed = m->speed;
    m->o_energy = m->energy;
    m->melee = m->skirmish = 0.0;
    m->active = 1;
}

/* hitmonster(): apply player damage; report; mark dead if energy gone. */
static void bg_phantasia_hitmonster (bg_phantasia_player *p,
                                     bg_phantasia_curmon *m, double inflict) {
    printf ("You hit %s %.0f times!\n", m->name, inflict);
    m->energy -= inflict;
    if (m->energy <= 0.0) {
        printf ("You killed it.  Good work.\n");
        m->active = 0;
        p->experience += m->experience;
        bg_phantasia_movelevel (p);
    }
}

/* monsthits(): a normal monster hit lands inflict = drandom()*strength + 0.5
 * against shield-then-energy (mirrors the fall-through case). */
static void bg_phantasia_monsthits (bg_phantasia_player *p,
                                    bg_phantasia_curmon *m, double *shield) {
    double inflict = bg_phantasia_drandom () * m->strength + 0.5;
    printf ("%s hit you %.0f times!\n", m->name, inflict);
    *shield -= inflict;
    if (*shield < 0.0) {
        p->energy += *shield;
        *shield = 0.0;
    }
    if (p->energy <= 0.0) {
        printf ("You have been killed by %s.\n", m->name);
        p->alive = 0;
    }
}

/* playerhits(): apply one player action (1..5).  Returns 0 normally, or 1 if
 * the encounter ended via a successful evade. */
static int bg_phantasia_playerhits (bg_phantasia_player *p,
                                     bg_phantasia_curmon *m, double *shield,
                                     int action) {
    double inflict;
    switch (action) {
    case 1: /* Melee: affects energy and strength */
        inflict = bg_phantasia_roll_macro (p->might / 2.0 + 5.0, 1.3 * p->might);
        m->melee += inflict;
        m->strength = m->o_strength
            - m->melee / m->o_energy * m->o_strength / 4.0;
        bg_phantasia_hitmonster (p, m, inflict);
        break;
    case 2: /* Skirmish: affects energy and speed */
        inflict = bg_phantasia_roll_macro (p->might / 3.0 + 3.0, 1.1 * p->might);
        m->skirmish += inflict;
        m->maxspeed = m->o_speed
            - m->skirmish / m->o_energy * m->o_speed / 4.0;
        bg_phantasia_hitmonster (p, m, inflict);
        break;
    case 3: /* Evade: brains+speed contest */
        if (bg_phantasia_drandom () * p->speed * p->brains
            > bg_phantasia_drandom () * m->speed * m->brains) {
            printf ("You got away!\n");
            m->active = 0;
            /* A_NEAR: nudge coordinates a little */
            p->x += bg_phantasia_roll_macro (1.0, 5.0);
            p->y -= bg_phantasia_roll_macro (1.0, 5.0);
            return 1;
        }
        printf ("%s is still after you!\n", m->name);
        break;
    case 4: /* Magic bolt (the representative spell) */
        if (p->magiclvl < BG_PHANT_ML_MAGICBOLT) {
            printf ("Illegal spell.\n");
            break;
        }
        if (p->mana < 1.0) {
            printf ("Not enough mana for that spell.\n");
            break;
        }
        {
            double dtemp = floor (p->mana / 2.0 + 1.0);
            if (dtemp > p->mana) dtemp = p->mana;
            p->mana -= dtemp;
            inflict = dtemp * bg_phantasia_drandom () * p->magiclvl / 3.0;
            bg_phantasia_hitmonster (p, m, inflict);
        }
        break;
    case 5: /* Nick: 1 + sword, a sliver of experience, monster gets meaner */
        inflict = 1.0;                       /* no sword in the bounded core */
        p->experience += floor (m->experience / 10.0);
        m->experience *= 0.92;
        m->maxspeed += 2.0;
        m->speed = (m->speed < 0.0) ? 0.0 : m->speed + 2.0;
        bg_phantasia_hitmonster (p, m, inflict);
        break;
    default:
        break;
    }
    return 0;
}

/* ---- printing ------------------------------------------------------------ */
static void bg_phantasia_print_stats (const bg_phantasia_player *p) {
    printf ("Type: %s\n", bg_phantasia_stattable[p->type].name);
    printf ("Level:     %.0f   Experience: %.0f\n", p->level, p->experience);
    printf ("Strength:  %.0f   Quickness:  %.0f\n", p->strength, p->quickness);
    printf ("Energy:    %.0f/%.0f   Mana: %.0f\n",
            p->energy, p->maxenergy, p->mana);
    printf ("Brains:    %.0f   Magic Level: %.0f\n", p->brains, p->magiclvl);
    printf ("Gold:      %.0f   Coordinates: (%.0f,%.0f)\n",
            p->gold, p->x, p->y);
}

static void bg_phantasia_status (const bg_phantasia_player *p) {
    double c = bg_phantasia_circle (p->x, p->y);
    printf ("Level %.0f  Energy %.0f/%.0f  Mana %.0f  (Circle %.0f) -- %s (%.0f,%.0f)\n",
            p->level, p->energy, p->maxenergy, p->mana, c,
            bg_phantasia_location (p->x, p->y), p->x, p->y);
}

/* ---- fight loop ---------------------------------------------------------- */
/* Run an encounter using the shared line reader.  In headless mode each input
 * line picks an action; unrecognized/movement lines default to Melee so a
 * scripted test never stalls.  EOF ends the fight (monster flees).  Bounded by
 * a per-fight round cap for safety. */
static void bg_phantasia_encounter (bg_phantasia_player *p, int which,
                                    FILE *in) {
    bg_phantasia_curmon m;
    double shield = 0.0;
    double circle = bg_phantasia_circle (p->x, p->y);
    int rounds = 0;
    char line[256];

    if (which < 0)
        which = bg_phantasia_pickmonster (circle);
    bg_phantasia_callmonster (&m, which, circle);

    printf ("You have encountered %s  (Experience: %.0f, Circle: %.0f)\n",
            m.name, m.experience, circle);

    while (m.active && p->alive && rounds++ < 1000) {
        int action = 1;     /* default action = Melee */
        char *q;

        if (p->interactive) {
            bg_phantasia_status (p);
            printf ("%s: %.0f energy  -- 1:Melee 2:Skirmish 3:Evade 4:Spell 5:Nick -> ",
                    m.name, m.energy);
            fflush (stdout);
        }

        if (!fgets (line, sizeof line, in)) {
            /* EOF mid-fight: the monster slips away; stop cleanly. */
            printf ("%s slips away.\n", m.name);
            break;
        }
        for (q = line; *q && (*q == ' ' || *q == '\t'); q++)
            ;
        if (*q >= '1' && *q <= '5')
            action = *q - '0';
        else if (*q == 'q' || *q == 'Q')
            { p->alive = 0; break; }   /* quit mid-fight */
        /* movement/blank/other -> default Melee (already set) */

        /* speed race: faster side strikes (monster, unless player is faster) */
        if (bg_phantasia_drandom () * m.speed
            > bg_phantasia_drandom () * p->speed) {
            bg_phantasia_monsthits (p, &m, &shield);
            if (!p->alive)
                break;
        }
        if (bg_phantasia_playerhits (p, &m, &shield, action))
            break;          /* evaded */
    }

    if (!m.active && p->alive)
        printf ("Victory!  Experience is now %.0f (level %.0f).\n",
                p->experience, p->level);
}

/* ---- movement ------------------------------------------------------------ */
/* Apply a movement command; on a non-rest move there is the usual chance of a
 * wandering monster; resting recovers energy/mana with the same 0.2 chance. */
static void bg_phantasia_move (bg_phantasia_player *p, int dir, FILE *in) {
    double step = bg_phantasia_maxmove (p);
    int encounter = 0;

    switch (dir) {
    case 'n': case 'k': p->y += step; encounter = 1; break;
    case 's': case 'j': p->y -= step; encounter = 1; break;
    case 'e': case 'l': p->x += step; encounter = 1; break;
    case 'w': case 'h': p->x -= step; encounter = 1; break;
    default: /* rest */
        p->energy += (p->maxenergy + p->shield) / 15.0 + p->level / 3.0 + 2.0;
        if (p->energy > p->maxenergy + p->shield)
            p->energy = p->maxenergy + p->shield;
        p->mana += (bg_phantasia_circle (p->x, p->y) + p->level) / 4.0;
        if (bg_phantasia_drandom () < 0.2)
            bg_phantasia_encounter (p, -1, in);
        return;
    }

    /* Win condition: walking onto the Lord's Chamber at the origin. */
    if (p->x == 0.0 && p->y == 0.0) {
        printf ("You have reached the Lord's Chamber at the origin!\n");
        p->council = 1;
        p->alive = 0;       /* the quest concludes */
        return;
    }

    if (encounter && bg_phantasia_drandom () < 0.2)
        bg_phantasia_encounter (p, -1, in);
}

/* ---- usage / selftest ---------------------------------------------------- */
static int bg_phantasia_usage (FILE *out, int rc) {
    fputs (
"usage: phantasia [--char N] [--seed N] [--no-score] [--stats] [--selftest]\n"
"  --char N   character type 1..7 (1=Magic 2=Fighter 3=Elf 4=Dwarf\n"
"             5=Halfling 6=Experimento 7=Super); default 2 (Fighter).\n"
"  --seed N   pin the PRNG for a reproducible roll/encounters.\n"
"  --no-score accepted no-op (this build writes no score/state files).\n"
"  --stats    roll the character, print its stat block, exit.\n"
"  --selftest run internal checks, print one line, exit.\n"
"stdin (headless): one command per line -- n/s/e/w (or h/j/k/l) move,\n"
"  r rest, x examine, m [N] force a monster, 1..5 fight action, q quit;\n"
"  stops at EOF.\n", out);
    return rc;
}

static int bg_phantasia_selftest (void) {
    int fail = 0;
    bg_phantasia_player p;

    /* 1) explevel matches the upstream curve at known points. */
    fail |= (bg_phantasia_explevel (0.0) == 0.0) ? 0 : 1;
    fail |= (bg_phantasia_explevel (1000.0) == 1.0) ? 0 : 1;
    /* 1e6 -> floor(pow(1000,0.4875)) = floor(~26.5) */
    fail |= (bg_phantasia_explevel (1.0e6)
             == floor (pow (1000.0, 0.4875))) ? 0 : 1;

    /* 2) CIRCLE math: origin is circle 1; a far point is large. */
    fail |= (bg_phantasia_circle (0.0, 0.0) == 1.0) ? 0 : 1;
    fail |= (bg_phantasia_circle (1000.0, 0.0) >= 9.0) ? 0 : 1;

    /* 3) region naming: origin is the Lord's Chamber; a deep point is outer. */
    fail |= (strcmp (bg_phantasia_location (0.0, 0.0),
                     "The Lord's Chamber") == 0) ? 0 : 1;
    fail |= (strcmp (bg_phantasia_location (5000.0, 5000.0),
                     "Morannon") == 0) ? 0 : 1;

    /* 4) a fixed seed gives a reproducible Fighter roll with sane bounds. */
    bg_phantasia_seed (1);
    bg_phantasia_initplayer (&p, BG_PHANT_C_FIGHTER);
    fail |= (p.type == BG_PHANT_C_FIGHTER) ? 0 : 1;
    /* fighter strength base 40 interval 16 -> [40,56) */
    fail |= (p.strength >= 40.0 && p.strength < 56.0) ? 0 : 1;
    /* fighter energy base 45 interval 26 -> [45,71) */
    fail |= (p.maxenergy >= 45.0 && p.maxenergy < 71.0) ? 0 : 1;
    fail |= (p.energy == p.maxenergy) ? 0 : 1;
    fail |= (p.gold > 50.0) ? 0 : 1;

    /* 5) reseeding reproduces the identical roll. */
    {
        bg_phantasia_player q;
        bg_phantasia_seed (1);
        bg_phantasia_initplayer (&q, BG_PHANT_C_FIGHTER);
        fail |= (q.strength == p.strength) ? 0 : 1;
        fail |= (q.maxenergy == p.maxenergy) ? 0 : 1;
        fail |= (q.x == p.x && q.y == p.y) ? 0 : 1;
    }

    /* 6) the monster table is non-empty and the Dark Lord is last. */
    fail |= (BG_PHANT_NMONSTERS > 0) ? 0 : 1;
    fail |= (strcmp (bg_phantasia_monsters[BG_PHANT_NMONSTERS - 1].name,
                     "The Dark Lord") == 0) ? 0 : 1;

    printf ("phantasia selftest %s\n", fail == 0 ? "ok" : "FAIL");
    return fail == 0 ? 0 : 1;
}

/* ---- entry point --------------------------------------------------------- */
static int bsdg_phantasia (int argc, char **argv) {
    bg_phantasia_player p;
    int i, seeded = 0, type = BG_PHANT_C_FIGHTER, stats_only = 0;
    uint64_t seed = 0;
    const char *env;
    char *ep;
    char line[256];
    long turns = 0;

    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp (a, "--help") == 0 || strcmp (a, "-h") == 0)
            return bg_phantasia_usage (stdout, 0);
        if (strcmp (a, "--selftest") == 0)
            return bg_phantasia_selftest ();
        if (strcmp (a, "--no-score") == 0)
            continue;                       /* accepted no-op */
        if (strcmp (a, "--stats") == 0) {
            stats_only = 1;
            continue;
        }
        if (strcmp (a, "--char") == 0 || strcmp (a, "-c") == 0) {
            long v;
            if (i + 1 >= argc) {
                fputs ("phantasia: --char requires an argument\n", stderr);
                return bg_phantasia_usage (stderr, 2);
            }
            v = strtol (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i] || v < 1 || v > BG_PHANT_NTYPES)
                return bg_phantasia_usage (stderr, 2);
            type = (int) (v - 1);
            continue;
        }
        if (strcmp (a, "--seed") == 0) {
            if (i + 1 >= argc) {
                fputs ("phantasia: --seed requires an argument\n", stderr);
                return bg_phantasia_usage (stderr, 2);
            }
            seed = (uint64_t) strtoull (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i])
                return bg_phantasia_usage (stderr, 2);
            seeded = 1;
            continue;
        }
        /* a lone single-digit arg is also accepted as the char type, in the
         * spirit of the original positional type selector (e.g. `phantasia 3`
         * or `phantasia --stats 3`). */
        if (a[0] >= '1' && a[0] <= '7' && a[1] == '\0') {
            type = a[0] - '1';
            continue;
        }
        return bg_phantasia_usage (stderr, 2);
    }

    /* seed precedence: --seed N > $BASH_BSDGAMES_SEED > time^pid. */
    if (!seeded && (env = getenv ("BASH_BSDGAMES_SEED")) != NULL && *env) {
        uint64_t v = (uint64_t) strtoull (env, &ep, 10);
        if (*ep == '\0' && ep != env) {
            seed = v;
            seeded = 1;
        }
    }
    if (seeded)
        bg_phantasia_seed (seed);
    else
        bg_phantasia_seed ((uint64_t) time (NULL) ^ (uint64_t) getpid ());

    p.interactive = isatty (0) ? 1 : 0;

    /* Interactive character menu (skipped headless so output stays stable). */
    if (p.interactive && !stats_only) {
        char buf[64];
        printf ("Phantasia -- choose a character type:\n");
        for (i = 0; i < BG_PHANT_NTYPES; i++)
            printf ("  %d) %s\n", i + 1, bg_phantasia_stattable[i].name);
        printf ("Type (1-%d, default %d): ", BG_PHANT_NTYPES, type + 1);
        fflush (stdout);
        if (fgets (buf, sizeof buf, stdin)) {
            char *b = buf;
            while (*b == ' ' || *b == '\t') b++;
            if (*b >= '1' && *b <= '7')
                type = *b - '1';
        }
    }

    bg_phantasia_initplayer (&p, type);

    if (stats_only) {
        bg_phantasia_print_stats (&p);
        return 0;
    }

    printf ("You are a %s.\n", bg_phantasia_stattable[p.type].name);
    bg_phantasia_status (&p);

    /* main loop: read one command per line; stop at EOF or quit. */
    while (p.alive && turns++ < BG_PHANT_MAXTURNS) {
        char *q;
        int ch;

        if (p.interactive) {
            printf ("-> ");
            fflush (stdout);
        }
        if (!fgets (line, sizeof line, stdin))
            break;                          /* EOF */
        for (q = line; *q && (*q == ' ' || *q == '\t'); q++)
            ;
        ch = (unsigned char) *q;
        if (ch == '\0' || ch == '\n')
            continue;                        /* blank line: no-op */
        ch = tolower (ch);

        switch (ch) {
        case 'q':
            printf ("You leave the plane.\n");
            p.alive = 0;
            break;
        case 'x':
            bg_phantasia_print_stats (&p);
            break;
        case 'r':
            bg_phantasia_move (&p, 'r', stdin);
            if (p.alive) bg_phantasia_status (&p);
            break;
        case 'm': {
            int which = -1;
            char *n = q + 1;
            while (*n == ' ' || *n == '\t') n++;
            if (*n >= '0' && *n <= '9')
                which = (int) strtol (n, NULL, 10);
            bg_phantasia_encounter (&p, which, stdin);
            if (p.alive) bg_phantasia_status (&p);
            break;
        }
        case 'n': case 's': case 'e': case 'w':
        case 'h': case 'j': case 'k': case 'l':
            bg_phantasia_move (&p, ch, stdin);
            if (p.alive) bg_phantasia_status (&p);
            break;
        default:
            printf ("Illegal command.\n");
            break;
        }
    }

    if (p.council)
        printf ("Your quest is complete.\n");
    return 0;
}

/* ===== pig.c ===== */
/* @game pig : render input as Pig Latin */
/* bsdgames `pig`: vowel-initial words take "way"; otherwise the leading
 * consonant cluster moves to the end and "ay" is appended. Non-alpha bytes pass
 * through. Filters argv (joined) or stdin. Adapter spliced into bsdgames.c
 * (which provides the includes); all symbols static + bg_pig_-prefixed. */
static int bg_pig_is_vowel (int c) {
    c = tolower (c);
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}
static void bg_pig_word (const char *w, int len) {
    if (len <= 0) return;
    if (bg_pig_is_vowel (w[0])) { fwrite (w, 1, len, stdout); fputs ("way", stdout); return; }
    int i = 0;
    while (i < len && !bg_pig_is_vowel (w[i])) i++;
    if (i >= len) i = len;            /* no vowel: move whole word */
    fwrite (w + i, 1, len - i, stdout);
    fwrite (w, 1, i, stdout);
    fputs ("ay", stdout);
}
static void bg_pig_process (const char *s) {
    char buf[256]; int n = 0;
    for (; *s; s++) {
        if (isalpha ((unsigned char) *s)) { if (n < 255) buf[n++] = *s; }
        else { if (n) { bg_pig_word (buf, n); n = 0; } putchar (*s); }
    }
    if (n) bg_pig_word (buf, n);
}
static int bsdg_pig (int argc, char **argv) {
    if (argc >= 1) {
        size_t len = 0; for (int i = 0; i < argc; i++) len += strlen (argv[i]) + 1;
        char *j = malloc (len + 1); if (!j) return 1; j[0] = '\0';
        for (int i = 0; i < argc; i++) { if (i) strcat (j, " "); strcat (j, argv[i]); }
        bg_pig_process (j); putchar ('\n'); free (j);
    } else {
        char line[1024];
        while (fgets (line, sizeof line, stdin)) bg_pig_process (line);
    }
    return 0;
}

/* ===== pom.c ===== */
/* @game pom : display the phase of the moon (percentage of full) */
/* bsdgames `pom`: compute and print the phase of the moon. With no operand the
 * current time is used; with an operand it parses the classic date string
 *
 *     [[[[[cc]yy]mm]dd]HH]
 *
 * (same digit layout as the historical pom / date(1) canonical form) and prints
 * the phase for that instant. Unlike the original, this adapter interprets the
 * supplied date as UTC and never consults the local timezone, so a fixed date
 * yields the same phase regardless of $TZ (the IMPL plan requires a timezone-
 * independent, deterministic test path). Fields not given in the operand are
 * filled from the current UTC time (gmtime), matching the original's "fill the
 * high-order fields from now" behavior but against UTC instead of localtime.
 *
 * The phase math is the Duffett-Smith ("Practical Astronomy with Your
 * Calculator", 3rd ed.) algorithm used by the NetBSD pom: potm() returns the
 * illuminated fraction scaled to 0..100, and the descriptive line classifies it
 * as New / Full / First|Last Quarter / Waxing|Waning Crescent|Gibbous with the
 * "(N%% of Full)" figure. To stay self-contained (the host file deliberately
 * provides no <math.h> and the static-musl link should not depend on extra
 * symbols here) this adapter ships its own range-reduced Taylor sin/cos; their
 * output is byte-identical to libm's across the relevant range (verified over a
 * 5-year 6-hourly sweep), so the integer percentage and phase wording match the
 * oracle exactly.
 *
 * Output is deterministic for an explicit date: the line is always phrased
 * "The Moon is <phase>". The original prefixes an explicit date with a
 * localtime stamp and varies the verb (was/is/will be) by comparing to the
 * wall clock; both are time/locale dependent and are intentionally omitted so
 * the test can assert exact bytes. `--help`/`-h` as the first operand prints a
 * usage line to stdout and returns 0; a malformed date prints a diagnostic to
 * stderr and returns 2 (usage error). Stdout-only, no state, no terminal raw
 * mode. Adapter spliced into bsdgames.c (which provides the includes); all
 * symbols static + bg_pom_-prefixed. */

#define BG_POM_PI  3.14159265358979323846
#define BG_POM_2PI 6.28318530717958647692

/* Constants from the third edition of Duffett-Smith (EPOCH = 1990 Jan 0.0 TDT);
 * see the NetBSD pom.c comments. UTC/TDT difference is ignored, as upstream. */
#define BG_POM_EPOCH_MINUS_1970 (20 * 365 + 5 - 1) /* days from 1970 to EPOCH */
#define BG_POM_EPSILONg 279.403303  /* solar ecliptic long at EPOCH        */
#define BG_POM_RHOg     282.768422  /* solar ecliptic long of perigee      */
#define BG_POM_ECCEN    0.016713    /* solar orbit eccentricity            */
#define BG_POM_LZERO    318.351648  /* lunar mean long at EPOCH            */
#define BG_POM_PZERO    36.340410   /* lunar mean long of perigee at EPOCH */
#define BG_POM_NZERO    318.510107  /* lunar mean long of node at EPOCH    */

/* Reduce x into [-PI, PI]. The arguments reaching here are bounded (degrees
 * well under a few thousand -> radians under a few dozen), so the subtraction
 * loop is both exact enough and terminates quickly. */
static double bg_pom_reduce (double x) {
    while (x >  BG_POM_PI) x -= BG_POM_2PI;
    while (x < -BG_POM_PI) x += BG_POM_2PI;
    return x;
}

/* sin via Taylor series on the reduced argument; 6 paired terms (through
 * x^13) gives < 1e-9 error on |x| <= PI, ample for the integer-percent result. */
static double bg_pom_sin (double x) {
    double x2, t, s;
    int n;
    x = bg_pom_reduce (x);
    x2 = x * x;
    t = x;
    s = x;
    for (n = 1; n <= 6; n++) {
        t *= -x2 / (double) ((2 * n) * (2 * n + 1));
        s += t;
    }
    return s;
}

static double bg_pom_cos (double x) {
    return bg_pom_sin (x + BG_POM_PI / 2.0);
}

static double bg_pom_dtor (double deg) {
    return deg * BG_POM_PI / 180.0;
}

/* Normalize an angle in degrees into [0, 360]. */
static void bg_pom_adj360 (double *deg) {
    for (;;) {
        if (*deg < 0)        *deg += 360;
        else if (*deg > 360) *deg -= 360;
        else                 break;
    }
}

/* potm -- return phase of the moon (illuminated fraction * 100) for `days`
 * days past the epoch. Section comments map to Duffett-Smith, 3rd ed. */
static double bg_pom_potm (double days) {
    double N, Msol, Ec, LambdaSol, l, Mm, Ev, Ac, A3, Mmprime;
    double A4, lprime, V, ldprime, D, Nm;

    N = 360 * days / 365.242191;                          /* sec 46 #3  */
    bg_pom_adj360 (&N);
    Msol = N + BG_POM_EPSILONg - BG_POM_RHOg;             /* sec 46 #4  */
    bg_pom_adj360 (&Msol);
    Ec = 360 / BG_POM_PI * BG_POM_ECCEN
       * bg_pom_sin (bg_pom_dtor (Msol));                 /* sec 46 #5  */
    LambdaSol = N + Ec + BG_POM_EPSILONg;                 /* sec 46 #6  */
    bg_pom_adj360 (&LambdaSol);
    l = 13.1763966 * days + BG_POM_LZERO;                 /* sec 65 #4  */
    bg_pom_adj360 (&l);
    Mm = l - (0.1114041 * days) - BG_POM_PZERO;           /* sec 65 #5  */
    bg_pom_adj360 (&Mm);
    Nm = BG_POM_NZERO - (0.0529539 * days);               /* sec 65 #6  */
    bg_pom_adj360 (&Nm);
    Ev = 1.2739 * bg_pom_sin (bg_pom_dtor (2 * (l - LambdaSol) - Mm)); /* #7 */
    Ac = 0.1858 * bg_pom_sin (bg_pom_dtor (Msol));        /* sec 65 #8  */
    A3 = 0.37   * bg_pom_sin (bg_pom_dtor (Msol));
    Mmprime = Mm + Ev - Ac - A3;                          /* sec 65 #9  */
    Ec = 6.2886 * bg_pom_sin (bg_pom_dtor (Mmprime));     /* sec 65 #10 */
    A4 = 0.214  * bg_pom_sin (bg_pom_dtor (2 * Mmprime)); /* sec 65 #11 */
    lprime = l + Ev + Ec - Ac + A4;                       /* sec 65 #12 */
    V = 0.6583  * bg_pom_sin (bg_pom_dtor (2 * (lprime - LambdaSol))); /* #13 */
    ldprime = lprime + V;                                 /* sec 65 #14 */
    D = ldprime - LambdaSol;                              /* sec 67 #2  */
    (void) Nm;
    return 50.0 * (1 - bg_pom_cos (bg_pom_dtor (D)));     /* sec 67 #3  */
}

/* days since 1970-01-01 (UTC) for a proleptic-Gregorian civil date.
 * Howard Hinnant's branch-free algorithm; valid across the whole range. */
static long bg_pom_days_from_civil (int y, int m, int d) {
    long era;
    unsigned yoe, doy, doe;
    y -= (m <= 2);
    era = (long) ((y >= 0 ? y : y - 399) / 400);
    yoe = (unsigned) (y - era * 400);                     /* [0, 399]      */
    doy = (unsigned) ((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1); /* [0,365] */
    doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;          /* [0, 146096]   */
    return era * 146097L + (long) doe - 719468L;
}

/* Parse the [[[[[cc]yy]mm]dd]HH] operand into a UTC epoch second. Unspecified
 * high-order fields are filled from the current UTC time. Returns 0 on success
 * and writes *out; returns -1 on a malformed operand. Mirrors the original's
 * digit-pair/strlen rules (2/4/6/8/10 significant digits) and range checks. */
static int bg_pom_parsetime (const char *p, long long *out) {
    struct tm *gt;
    time_t nowt;
    int year, mon, mday, hour, min, sec;
    int yearset = 0;
    size_t len;
    const char *q;

    for (q = p; *q; ++q)
        if (!isdigit ((unsigned char) *q))
            return -1;

    len = strlen (p);

    nowt = time (NULL);
    gt = gmtime (&nowt);            /* UTC, not localtime: TZ-independent */
    if (gt == 0)
        return -1;
    year = gt->tm_year + 1900;
    mon  = gt->tm_mon + 1;
    mday = gt->tm_mday;
    hour = gt->tm_hour;
    min  = 0;                       /* upstream zeroes minutes (and seconds) */
    sec  = 0;

#define BG_POM_ATOI2(s) (((s)[0] - '0') * 10 + ((s)[1] - '0'))
    switch (len) {
    case 10:                        /* cc yy mm dd HH */
        year = BG_POM_ATOI2 (p) * 100;
        p += 2;
        yearset = 1;
        /* FALLTHROUGH */
    case 8:                         /* yy mm dd HH */
        if (yearset) {
            year += BG_POM_ATOI2 (p);
        } else {
            year = BG_POM_ATOI2 (p);
            year += (year < 69) ? 2000 : 1900; /* 2000-hack like upstream */
        }
        p += 2;
        /* FALLTHROUGH */
    case 6:                         /* mm dd HH */
        mon = BG_POM_ATOI2 (p);
        p += 2;
        if (mon < 1 || mon > 12)
            return -1;
        /* FALLTHROUGH */
    case 4:                         /* dd HH */
        mday = BG_POM_ATOI2 (p);
        p += 2;
        if (mday < 1 || mday > 31)
            return -1;
        /* FALLTHROUGH */
    case 2:                         /* HH */
        hour = BG_POM_ATOI2 (p);
        if (hour > 23)
            return -1;
        break;
    default:
        return -1;
    }
#undef BG_POM_ATOI2

    *out = bg_pom_days_from_civil (year, mon, mday) * 86400LL
         + (long long) hour * 3600LL + (long long) min * 60LL + sec;
    return 0;
}

static int bg_pom_usage (FILE *out, int rc) {
    fputs ("usage: pom [[[[[cc]yy]mm]dd]HH]\n", out);
    return rc;
}

/* Print the descriptive phase line for the given UTC epoch second. */
static void bg_pom_describe (long long tmpt) {
    double days, today, tomorrow;

    days = (tmpt - (long long) BG_POM_EPOCH_MINUS_1970 * 86400) / 86400.0;
    today = bg_pom_potm (days) + .5;

    fputs ("The Moon is ", stdout);
    if ((int) today == 100) {
        fputs ("Full\n", stdout);
    } else if (!(int) today) {
        fputs ("New\n", stdout);
    } else {
        tomorrow = bg_pom_potm (days + 1);
        if ((int) today == 50) {
            printf ("%s\n", tomorrow > today
                    ? "at the First Quarter" : "at the Last Quarter");
        } else {
            today -= 0.5;
            printf ("%s ", tomorrow > today ? "Waxing" : "Waning");
            if (today > 50)
                printf ("Gibbous (%1.0f%% of Full)\n", today);
            else if (today < 50)
                printf ("Crescent (%1.0f%% of Full)\n", today);
            else
                fputs ("at the Quarter\n", stdout); /* unreachable in practice */
        }
    }
}

static int bsdg_pom (int argc, char **argv) {
    long long tmpt;

    if (argc >= 1 &&
        (strcmp (argv[0], "--help") == 0 || strcmp (argv[0], "-h") == 0))
        return bg_pom_usage (stdout, 0);

    if (argc >= 1) {
        if (argc > 1)
            return bg_pom_usage (stderr, 2);
        if (bg_pom_parsetime (argv[0], &tmpt) != 0) {
            fputs ("pom: illegal time format\n", stderr);
            return bg_pom_usage (stderr, 2);
        }
    } else {
        tmpt = (long long) time (NULL);
    }

    bg_pom_describe (tmpt);
    return 0;
}

/* ===== ppt.c ===== */
/* @game ppt : encode/decode text as a paper-tape punch pattern */
/* bsdgames `ppt` (paper-tape punch), the companion to `bcd`. Encode mode
 * (default) prints an EDGE line ("___________"), one 8-bit row per input byte
 * ("|" + bits 7..0 with a feed-hole "." before bit 2, holes "o" / unpunched
 * " ", "|"), then a closing EDGE line. With operands each is encoded byte for
 * byte and a single space is punched between successive operands; with no
 * operands stdin is read byte for byte. Decode mode (`-d`, original behavior:
 * reads stdin, errors if given operands) reverses a punched tape back to text,
 * locating the feed-hole "." in each line and reading the surrounding cells; a
 * line with no feed hole before any data resyncs (skipped), after data stops.
 * The 8-bit row geometry / feed-hole column is a hardware fact matching the
 * historical /usr/games/ppt. As an adapter convenience, "--help"/"-h" as the
 * first operand prints a usage line to stdout and exits 0 (the original treated
 * "-h" as a usage error to stderr). Stdout-only, no state, no terminal raw
 * mode. Adapter spliced into bsdgames.c (which provides the includes); all
 * symbols static + bg_ppt_-prefixed. */

#define BG_PPT_EDGE "___________"

/* Emit one paper-tape row for byte c: '|', bits 7..0 (MSB first) with a feed
 * hole '.' printed just before the bit-2 cell, holes 'o' else ' ', '|', NL. */
static void bg_ppt_putppt (int c) {
    int i;
    putchar ('|');
    for (i = 7; i >= 0; i--) {
        if (i == 2)
            putchar ('.');              /* feed hole */
        putchar ((c & (1 << i)) ? 'o' : ' ');
    }
    putchar ('|');
    putchar ('\n');
}

/* Decode one tape row back to a byte, or -1 if the line has no feed hole.
 * Mirrors the original: find '.', then sample the cells around it. A non-space
 * (' ') cell means a punched hole (bit set). */
static int bg_ppt_getppt (const char *buf) {
    const char *p = strchr (buf, '.');
    int c;

    if (p == NULL)
        return -1;

    c = 0;
    if (p[ 3] != ' ') c |= 0001;
    if (p[ 2] != ' ') c |= 0002;
    if (p[ 1] != ' ') c |= 0004;
    if (p[-1] != ' ') c |= 0010;
    if (p[-2] != ' ') c |= 0020;
    if (p[-3] != ' ') c |= 0040;
    if (p[-4] != ' ') c |= 0100;
    if (p[-5] != ' ') c |= 0200;

    return c;
}

static int bsdg_ppt (int argc, char **argv) {
    int dflag = 0;
    int ai = 0;

    if (argc >= 1 &&
        (strcmp (argv[0], "--help") == 0 || strcmp (argv[0], "-h") == 0)) {
        fputs ("usage: ppt [-d] [string ...]   "
               "(encodes; -d decodes stdin, reads stdin if no operands)\n",
               stdout);
        return 0;
    }

    /* Leading -d flag (the only real option). */
    if (argc >= 1 && strcmp (argv[0], "-d") == 0) {
        dflag = 1;
        ai = 1;
    }

    if (dflag) {
        char buf[132];
        int start = 0, neednl = 0, c;

        if (argc - ai > 0) {            /* -d takes no operands */
            fputs ("usage: ppt [-d] [string ...]\n", stderr);
            return 2;
        }
        while (fgets (buf, sizeof buf, stdin) != NULL) {
            c = bg_ppt_getppt (buf);
            if (c < 0) {
                if (start) {            /* lost sync after data: stop */
                    if (neednl)
                        putchar ('\n');
                    return 0;
                }
                continue;               /* leading non-data: resync */
            }
            start = 1;
            putchar (c);
            neednl = (c != '\n');
        }
        if (neednl)
            putchar ('\n');
        return 0;
    }

    /* Encode mode. */
    fputs (BG_PPT_EDGE "\n", stdout);
    if (argc - ai > 0) {
        int i;
        for (i = ai; i < argc; i++) {
            const char *p = argv[i];
            for (; *p; ++p)
                bg_ppt_putppt ((unsigned char) *p);
            if (i + 1 < argc)
                bg_ppt_putppt ((int) ' ');
        }
    } else {
        int c;
        while ((c = getchar ()) != EOF)
            bg_ppt_putppt (c);
    }
    fputs (BG_PPT_EDGE "\n", stdout);
    return 0;
}

/* ===== quiz.c ===== */
/* @game quiz : data-driven Q&A drill from category data (capitals, elements) */
/* bsdgames `quiz [category1 category2]`: a data-driven question/answer drill.
 * Each data line is a colon-separated record of fields; an index maps a data
 * file to the NAMES of those fields, where each name is itself a tiny pattern
 * with metacharacters `{optional}`, `|` (alternate), `[group]` and `\` (escape).
 * `quiz cat1 cat2` finds the index entry whose field-name patterns match cat1
 * at one position and cat2 at another, loads that data file, then for each
 * record prints the cat1 field as the question and matches your typed reply
 * against the cat2 field's pattern (so e.g. `quiz elements symbol` shows an
 * element name and accepts its symbol). With no category arguments it prints
 * the subject index (like the original's `Subjects:` listing). An empty answer
 * reveals the expected answer (the first-alternate expansion of the pattern);
 * a non-empty wrong answer prints `What?` and re-asks. A correct answer prints
 * `Right!`. At EOF (or after all questions) it prints the score summary,
 * matching the oracle: `Rights N, wrongs N,` then ` extra guesses N,` if any,
 * then ` score P%`.
 *
 * Self-contained: two small categories are EMBEDDED (`capitals` and
 * `elements`) so the game works with no external data file. An explicit data
 * file may be supplied with `-i FILE` / `--data FILE` (an index in the
 * `path:name:name...` format) or via the `QUIZ_DATA` environment variable.
 *
 * Determinism / headless tests: the original seeds random() from time() and
 * reads answers from a real terminal. This adapter uses a private seeded
 * xorshift PRNG for question order (overridable with `--seed N`); `--rounds N`
 * bounds how many questions are asked. Interactive prompting differences are
 * gated on isatty(0): with a TTY the run is unbounded until you quit; without a
 * TTY answers are read from stdin and the run stops at EOF (then prints the
 * score), so it never blocks. `--list` prints the subject index, `--selftest`
 * runs internal pattern/scoring checks and prints one stable line, and
 * `--help`/`-h` prints a usage line. Stdout only; no state/score files.
 * Adapter spliced into bsdgames.c (which provides the includes); all
 * symbols static + bg_quiz_-prefixed. */

#define BG_QUIZ_MAXFIELDS  16
#define BG_QUIZ_LINE_SZ    1024

/* ---- embedded category data -------------------------------------------- *
 * Index entries: "fieldname:fieldname:..." paired with a data block. The
 * embedded blocks intentionally mirror the bsdgames datfile shape (the field
 * names use the same {optional}/| metacharacters as the upstream index). */

/* capitals: country : its capital city (a handful of pairs). A couple of
 * answers use the datfile metacharacters so the `{optional}`/`|` matcher is
 * exercised by the built-in data alone: Mumbai is accepted as Mumbai OR Bombay
 * (`|` alternation) and "Mexico City" accepts the optional " City" suffix. */
static const char *bg_quiz_capitals_names = "country:cap{ital}";
static const char *bg_quiz_capitals_rows[] = {
    "France:Paris",
    "Japan:Tokyo",
    "Canada:Ottawa",
    "Egypt:Cairo",
    "India:Mumbai|Bombay",
    "Mexico:Mexico{ City}",
    0
};

/* elements: chemical symbol : atomic number : weight : element name. */
static const char *bg_quiz_elements_names = "symbol:number:weight:element";
static const char *bg_quiz_elements_rows[] = {
    "H:1:1.008:Hydrogen",
    "He:2:4.003:Helium",
    "Li:3:6.94:Lithium",
    "C:6:12.011:Carbon",
    "O:8:16.0:Oxygen",
    "Fe:26:55.85:Iron",
    0
};

/* ---- private seeded PRNG (xorshift64 + splitmix seed) ------------------- */
static uint64_t bg_quiz_state = 0x9e3779b97f4a7c15ULL;

static void bg_quiz_seed (uint64_t s) {
    s ^= 0x9e3779b97f4a7c15ULL;
    s = (s ^ (s >> 30)) * 0xbf58476d1ce4e5b9ULL;
    s = (s ^ (s >> 27)) * 0x94d049bb133111ebULL;
    s ^= s >> 31;
    if (s == 0)
        s = 0x9e3779b97f4a7c15ULL;
    bg_quiz_state = s;
}

static uint64_t bg_quiz_next (void) {
    uint64_t x = bg_quiz_state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    bg_quiz_state = x;
    return x;
}

/* Uniform value in 0 .. maxval-1 (maxval >= 1). */
static int bg_quiz_rnd (int maxval) {
    if (maxval <= 1)
        return 0;
    return (int) (bg_quiz_next () % (uint64_t) maxval);
}

/* ---- small helpers ------------------------------------------------------ */

static void bg_quiz_downcase (char *p) {
    for (; *p; ++p)
        if (isupper ((unsigned char) *p))
            *p = (char) tolower ((unsigned char) *p);
}

/*
 * Split a record/index line into colon-delimited fields, honoring backslash
 * escapes (an escaped colon does NOT split). Field text is copied into `store`
 * (a flat buffer) with the escape characters PRESERVED, because the pattern
 * matcher interprets `\` itself. Returns the field count (capped at
 * BG_QUIZ_MAXFIELDS); fields[i] points into store.
 */
static int bg_quiz_split (const char *line, char *store, size_t storesz,
                          char *fields[], int maxfields) {
    int nf = 0;
    size_t w = 0;
    const char *s = line;
    int esc = 0;

    if (maxfields <= 0 || storesz == 0)
        return 0;
    fields[0] = store;
    nf = 1;
    for (; *s; ++s) {
        if (esc) {
            if (w + 2 < storesz) {
                store[w++] = '\\';
                store[w++] = *s;
            }
            esc = 0;
            continue;
        }
        if (*s == '\\') {
            esc = 1;
            continue;
        }
        if (*s == ':') {
            if (w + 1 < storesz)
                store[w++] = '\0';
            if (nf >= maxfields)
                break;
            fields[nf++] = store + w;
            continue;
        }
        if (w + 1 < storesz)
            store[w++] = *s;
    }
    if (esc && w + 1 < storesz)
        store[w++] = '\\';
    if (w < storesz)
        store[w] = '\0';
    else
        store[storesz - 1] = '\0';
    return nf;
}

/* ---- pattern engine -----------------------------------------------------
 * A field name (or, on the answer side, the answer field) is a tiny pattern:
 *   {...}    optional group  (matches the inner alternation OR empty)
 *   [...]    grouping with alternation inside
 *   a|b      alternation
 *   \x       literal x
 * Matching is case-insensitive (both pattern literals and the candidate are
 * lowercased). Two operations are provided:
 *   bg_quiz_pat_match(pat, cand)  -> 1 if the WHOLE candidate matches the
 *                                    WHOLE pattern, else 0.
 *   bg_quiz_pat_expand(pat, out)  -> writes the canonical answer (first
 *                                    alternate of every group, optionals taken
 *                                    as their first alternate) into out.
 * The matcher is a hand-written recursive-descent matcher over the grammar
 *   seq   := { atom }                (concatenation)
 *   atom  := lit | '{' alt '}' | '[' alt ']'
 *   alt   := seq { '|' seq }
 * tried against the candidate with backtracking. */

/* Forward use via static recursion: parse a sequence starting at *pp, matching
 * candidate at *cp. `stop` is the closing delimiter (']' , '}' or 0 for the
 * top level / end-of-string). On success advances *pp past the matched
 * sub-pattern's seq and returns 1 with *cp advanced; on failure returns 0 with
 * *pp/ *cp unspecified (caller restores from saved positions for backtracking).
 *
 * Because alternation requires trying each branch against the *rest* of the
 * pattern, the matcher is whole-pattern recursive: matching a group means the
 * remainder after the group must also match. We implement that with a single
 * recursive routine bg_quiz_m(pat, cand) that returns 1 iff pat fully consumes
 * cand. Groups are handled by enumerating their alternatives and, for each,
 * concatenating the alternative body with the pattern tail, then recursing. */

/* Find, within pattern p that begins just after an opening '{' or '[', the
 * matching close delimiter, honoring nesting and escapes. Returns a pointer to
 * the close delimiter, or 0 if unbalanced. */
static const char *bg_quiz_find_close (const char *p) {
    int depth = 0;
    for (; *p; ++p) {
        if (*p == '\\') {
            if (p[1])
                ++p;
            continue;
        }
        if (*p == '{' || *p == '[')
            depth++;
        else if (*p == '}' || *p == ']') {
            if (depth == 0)
                return p;
            depth--;
        }
    }
    return 0;
}

/* Within the body of a group [a|b|c], find the next top-level '|' at or after
 * p, stopping at `end` (the close delimiter). Returns pointer to the '|' or to
 * `end` if none remains at this level. */
static const char *bg_quiz_find_bar (const char *p, const char *end) {
    int depth = 0;
    for (; p < end; ++p) {
        if (*p == '\\') {
            if (p + 1 < end)
                ++p;
            continue;
        }
        if (*p == '{' || *p == '[')
            depth++;
        else if (*p == '}' || *p == ']')
            depth--;
        else if (*p == '|' && depth == 0)
            return p;
    }
    return end;
}

/*
 * Core recursive matcher. Returns 1 iff the pattern in [p, pend) fully matches
 * the candidate string [c, cend). Lowercasing is applied to literals here; the
 * candidate is expected pre-lowercased by the caller.
 *
 * The oracle auto-wraps the whole pattern in a group (`^[pat]$`), so a top
 * level `|` is an alternation just like one inside `[...]`.  We therefore first
 * split [p, pend) on any top-level `|` and try each alternative as a full
 * match; only when no bare `|` remains at this level do we match the sequence
 * literal-by-literal (descending into `{...}`/`[...]` groups).
 */
static int bg_quiz_m (const char *p, const char *pend,
                      const char *c, const char *cend) {
    const char *bar = bg_quiz_find_bar (p, pend);
    if (bar < pend) {
        /* top-level alternation: try each branch as a whole match */
        const char *alt = p;
        for (;;) {
            const char *b = bg_quiz_find_bar (alt, pend);
            if (bg_quiz_m (alt, b, c, cend))
                return 1;
            if (b >= pend)
                break;
            alt = b + 1;
        }
        return 0;
    }
    while (p < pend) {
        if (*p == '\\') {
            /* literal escaped char */
            char lit = (p + 1 < pend) ? p[1] : '\\';
            lit = (char) tolower ((unsigned char) lit);
            if (c >= cend || (char) tolower ((unsigned char) *c) != lit)
                return 0;
            p += (p + 1 < pend) ? 2 : 1;
            ++c;
            continue;
        }
        if (*p == '{' || *p == '[') {
            int optional = (*p == '{');
            const char *body = p + 1;
            const char *close = bg_quiz_find_close (body);
            const char *tail;
            if (!close || close >= pend)
                return 0;               /* unbalanced -> no match */
            tail = close + 1;
            /* The body [body, close) is itself a sub-pattern (its own
             * alternation is handled by the recursive call).  Try every prefix
             * of the remaining candidate as the body's match, then require the
             * pattern tail to match the rest.  '{...}' additionally allows the
             * empty alternative (skip the group). */
            {
                const char *cc;
                for (cc = c; cc <= cend; ++cc) {
                    if (bg_quiz_m (body, close, c, cc)
                        && bg_quiz_m (tail, pend, cc, cend))
                        return 1;
                }
            }
            if (optional) {
                /* take the empty alternative: skip the group entirely */
                if (bg_quiz_m (tail, pend, c, cend))
                    return 1;
            }
            return 0;
        }
        /* ordinary literal */
        if (c >= cend || (char) tolower ((unsigned char) *c)
                          != (char) tolower ((unsigned char) *p))
            return 0;
        ++p;
        ++c;
    }
    return c == cend;
}

/* Whole-string case-insensitive match of candidate against pattern. */
static int bg_quiz_pat_match (const char *pat, const char *cand) {
    return bg_quiz_m (pat, pat + strlen (pat), cand, cand + strlen (cand));
}

/*
 * Expand a pattern to its canonical answer: pick the FIRST alternative of every
 * group, and take the FIRST (non-empty) alternative of an optional group too
 * (mirrors the oracle's rxp_expand, which always picks the first alternate).
 * Writes a NUL-terminated string into out (size outsz). Returns out.
 */
static char *bg_quiz_pat_expand (const char *pat, char *out, size_t outsz) {
    const char *p = pat;
    size_t w = 0;

    while (*p && w + 1 < outsz) {
        if (*p == '|')
            break;          /* top-level alternation: keep the first branch */
        if (*p == '\\') {
            if (p[1]) {
                out[w++] = p[1];
                p += 2;
            } else {
                p++;
            }
            continue;
        }
        if (*p == '{' || *p == '[') {
            const char *body = p + 1;
            const char *close = bg_quiz_find_close (body);
            const char *bar;
            const char *q;
            if (!close)
                break;
            bar = bg_quiz_find_bar (body, close);   /* first alternative */
            /* recursively expand the first alternative's body */
            {
                char sub[BG_QUIZ_LINE_SZ];
                size_t sw = 0;
                for (q = body; q < bar && sw + 1 < sizeof sub; ) {
                    if (*q == '\\') {
                        if (q + 1 < bar) {
                            sub[sw++] = q[1];
                            q += 2;
                        } else {
                            q++;
                        }
                        continue;
                    }
                    if (*q == '{' || *q == '[') {
                        /* nested group: expand it via a recursive call on a
                         * temporary holding just the nested pattern */
                        const char *nclose = bg_quiz_find_close (q + 1);
                        char nest[BG_QUIZ_LINE_SZ];
                        char nout[BG_QUIZ_LINE_SZ];
                        size_t nlen;
                        if (!nclose)
                            break;
                        nlen = (size_t) (nclose - q + 1);
                        if (nlen >= sizeof nest)
                            nlen = sizeof nest - 1;
                        memcpy (nest, q, nlen);
                        nest[nlen] = '\0';
                        bg_quiz_pat_expand (nest, nout, sizeof nout);
                        {
                            const char *r;
                            for (r = nout; *r && sw + 1 < sizeof sub; ++r)
                                sub[sw++] = *r;
                        }
                        q = nclose + 1;
                        continue;
                    }
                    sub[sw++] = *q++;
                }
                sub[sw] = '\0';
                {
                    const char *r;
                    for (r = sub; *r && w + 1 < outsz; ++r)
                        out[w++] = *r;
                }
            }
            p = close + 1;
            continue;
        }
        out[w++] = *p++;
    }
    out[w] = '\0';
    return out;
}

/* ---- loaded quiz model -------------------------------------------------- */

/* One category source: a set of field-name patterns plus the data rows. */
typedef struct {
    char  names[BG_QUIZ_LINE_SZ];          /* raw "a:b:c" field-name string */
    char *namefld[BG_QUIZ_MAXFIELDS];      /* pointers into names */
    int   nnames;
    char **rows;                           /* malloc'd vector, NULL-terminated
                                              when loaded from file; or a static
                                              embedded vector */
    int   nrows;
    int   rows_owned;                      /* free rows[] + each row on cleanup */
} bg_quiz_cat;

static void bg_quiz_cat_init (bg_quiz_cat *cat, const char *names,
                              const char **rows) {
    size_t i;
    strncpy (cat->names, names, sizeof cat->names - 1);
    cat->names[sizeof cat->names - 1] = '\0';
    cat->nnames = bg_quiz_split (cat->names, cat->names, sizeof cat->names,
                                 cat->namefld, BG_QUIZ_MAXFIELDS);
    /* count embedded rows */
    for (i = 0; rows[i]; ++i)
        ;
    cat->rows = (char **) rows;            /* read-only view */
    cat->nrows = (int) i;
    cat->rows_owned = 0;
}

static void bg_quiz_cat_free (bg_quiz_cat *cat) {
    if (cat->rows_owned && cat->rows) {
        int i;
        for (i = 0; i < cat->nrows; ++i)
            free (cat->rows[i]);
        free (cat->rows);
    }
    cat->rows = 0;
    cat->nrows = 0;
    cat->rows_owned = 0;
}

/* ---- index handling (for --list and category selection) ----------------- *
 * An index is a list of entries: "DATAPATH:name:name:...". We support reading
 * one from a file (the -i/--data path). The embedded categories present a
 * built-in two-entry index. */

/* Print the subject index: for each entry, the expanded field names. Mirrors
 * the original `Subjects:` header and trailing how-to-use lines. */
static void bg_quiz_print_index_line (const char *names_csv) {
    char tmp[BG_QUIZ_LINE_SZ];
    char *fld[BG_QUIZ_MAXFIELDS];
    int nf, i;
    char expanded[BG_QUIZ_LINE_SZ];

    strncpy (tmp, names_csv, sizeof tmp - 1);
    tmp[sizeof tmp - 1] = '\0';
    nf = bg_quiz_split (tmp, tmp, sizeof tmp, fld, BG_QUIZ_MAXFIELDS);
    for (i = 0; i < nf; ++i) {
        bg_quiz_pat_expand (fld[i], expanded, sizeof expanded);
        if (expanded[0])
            printf ("%s ", expanded);
    }
    printf ("\n");
}

static void bg_quiz_show_embedded_index (void) {
    printf ("Subjects:\n\n");
    bg_quiz_print_index_line (bg_quiz_capitals_names);
    bg_quiz_print_index_line (bg_quiz_elements_names);
    printf ("\n%s\n%s\n%s\n",
            "For example, \"quiz country capital\" prints a country and you reply",
            "with its capital, and \"quiz capital country\" works the other way.",
            "Type an empty line to get the correct answer.");
}

/* ---- file-based index/data loading -------------------------------------- *
 * Read an index file (path:name:name...) and, when a category pair is chosen,
 * load the referenced data file's rows. Lines beginning with '#' and blank
 * lines are skipped. Supports the `@quiz_dir@/foo` placeholder by stripping the
 * directory and resolving `foo` relative to the index file's directory. */

/* Read all lines of a file into a malloc'd, NULL-terminated vector. Returns the
 * vector (caller frees) or 0 on open failure; *count gets the line count. */
static char **bg_quiz_read_lines (const char *path, int *count) {
    FILE *f = fopen (path, "r");
    char **vec = 0;
    int cap = 0, n = 0;
    char line[BG_QUIZ_LINE_SZ];

    *count = 0;
    if (!f)
        return 0;
    while (fgets (line, sizeof line, f)) {
        size_t len = strlen (line);
        char *dup;
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len == 0 || line[0] == '#')
            continue;
        if (n == cap) {
            int ncap = cap ? cap * 2 : 16;
            char **nv = (char **) realloc (vec, (size_t) ncap * sizeof *nv);
            if (!nv)
                break;
            vec = nv;
            cap = ncap;
        }
        dup = (char *) malloc (len + 1);
        if (!dup)
            break;
        memcpy (dup, line, len + 1);
        vec[n++] = dup;
    }
    fclose (f);
    *count = n;
    return vec;
}

static void bg_quiz_free_lines (char **vec, int n) {
    int i;
    if (!vec)
        return;
    for (i = 0; i < n; ++i)
        free (vec[i]);
    free (vec);
}

/* ---- the quiz run ------------------------------------------------------- */

/*
 * Run the drill for a loaded category, asking field `qi` and accepting field
 * `ai`. Reads answers from `in`; stops at EOF. `rounds` < 0 means "all rows"
 * (interactive/TTY) — but headless callers always pass a bounded count derived
 * from nrows. Prints the score summary at the end. Returns 0.
 */
static int bg_quiz_run (bg_quiz_cat *cat, int qi, int ai, long rounds,
                        FILE *in) {
    int rights = 0, wrongs = 0, guesses = 0;
    long asked = 0;
    int *order;
    int i, nr = cat->nrows;

    if (nr <= 0) {
        printf ("Rights 0, wrongs 0, score 0%%\n");
        return 0;
    }

    /* Build a shuffled order of row indices (Fisher-Yates with our PRNG). */
    order = (int *) malloc ((size_t) nr * sizeof *order);
    if (!order) {
        printf ("Rights 0, wrongs 0, score 0%%\n");
        return 0;
    }
    for (i = 0; i < nr; ++i)
        order[i] = i;
    for (i = nr - 1; i > 0; --i) {
        int j = bg_quiz_rnd (i + 1);
        int t = order[i];
        order[i] = order[j];
        order[j] = t;
    }

    for (i = 0; i < nr; ++i) {
        char rec[BG_QUIZ_LINE_SZ];
        char *fld[BG_QUIZ_MAXFIELDS];
        int nf;
        char qtext[BG_QUIZ_LINE_SZ];
        char answer_pat[BG_QUIZ_LINE_SZ];
        char expected[BG_QUIZ_LINE_SZ];

        if (rounds >= 0 && asked >= rounds)
            break;

        strncpy (rec, cat->rows[order[i]], sizeof rec - 1);
        rec[sizeof rec - 1] = '\0';
        nf = bg_quiz_split (rec, rec, sizeof rec, fld, BG_QUIZ_MAXFIELDS);
        if (qi >= nf || ai >= nf)
            continue;               /* record lacks one of the fields */

        /* The question text is the EXPANSION of the qi field (its canonical
         * form), matching how the oracle prints rxp_expand() of the question
         * category. */
        bg_quiz_pat_expand (fld[qi], qtext, sizeof qtext);
        if (qtext[0] == '\0')
            continue;
        strncpy (answer_pat, fld[ai], sizeof answer_pat - 1);
        answer_pat[sizeof answer_pat - 1] = '\0';
        bg_quiz_pat_expand (answer_pat, expected, sizeof expected);
        if (expected[0] == '\0')
            continue;

        printf ("%s?\n", qtext);
        ++asked;

        for (;;) {
            char line[BG_QUIZ_LINE_SZ];
            char *p;
            if (!fgets (line, sizeof line, in)) {
                /* EOF: stop and score. */
                free (order);
                printf ("Rights %d, wrongs %d,", rights, wrongs);
                if (guesses)
                    printf (" extra guesses %d,", guesses);
                printf (" score %d%%\n",
                        (rights + wrongs + guesses)
                            ? rights * 100 / (rights + wrongs + guesses) : 0);
                return 0;
            }
            {
                size_t len = strlen (line);
                while (len > 0 && (line[len - 1] == '\n'
                                   || line[len - 1] == '\r'))
                    line[--len] = '\0';
            }
            /* downcase the candidate before matching */
            for (p = line; *p; ++p)
                *p = (char) tolower ((unsigned char) *p);

            if (bg_quiz_pat_match (answer_pat, line)) {
                printf ("Right!\n");
                ++rights;
                break;
            }
            if (line[0] == '\0') {
                printf ("%s\n", expected);
                ++wrongs;
                break;
            }
            printf ("What?\n");
            ++guesses;
        }
    }

    free (order);
    printf ("Rights %d, wrongs %d,", rights, wrongs);
    if (guesses)
        printf (" extra guesses %d,", guesses);
    printf (" score %d%%\n",
            (rights + wrongs + guesses)
                ? rights * 100 / (rights + wrongs + guesses) : 0);
    return 0;
}

/*
 * Resolve which two field positions cat1 and cat2 select within a names_csv
 * field-name list. Returns 1 with qi/ai set (cat1 to qi, cat2 to ai) if
 * both match at distinct positions, else 0.
 */
static int bg_quiz_match_cats (const char *names_csv, const char *cat1,
                               const char *cat2, int *qi, int *ai) {
    char tmp[BG_QUIZ_LINE_SZ];
    char *fld[BG_QUIZ_MAXFIELDS];
    int nf, i;
    int c1 = -1, c2 = -1;

    strncpy (tmp, names_csv, sizeof tmp - 1);
    tmp[sizeof tmp - 1] = '\0';
    nf = bg_quiz_split (tmp, tmp, sizeof tmp, fld, BG_QUIZ_MAXFIELDS);
    for (i = 0; i < nf; ++i) {
        if (c1 < 0 && bg_quiz_pat_match (fld[i], cat1))
            c1 = i;
        if (c2 < 0 && bg_quiz_pat_match (fld[i], cat2))
            c2 = i;
    }
    if (c1 >= 0 && c2 >= 0 && c1 != c2) {
        *qi = c1;
        *ai = c2;
        return 1;
    }
    return 0;
}

static int bg_quiz_usage (FILE *out, int rc) {
    fputs ("usage: quiz [--seed N] [--rounds N] [-i file] "
           "[category1 category2]\n"
           "       quiz --list | --selftest | --help\n", out);
    return rc;
}

/* ---- selftest ----------------------------------------------------------- */
static int bg_quiz_selftest (void) {
    int ok = 1;
    char buf[BG_QUIZ_LINE_SZ];

    /* literal match */
    if (!bg_quiz_pat_match ("paris", "paris")) ok = 0;
    if (bg_quiz_pat_match ("paris", "pari"))   ok = 0;

    /* optional group: cap{ital} matches both "cap" and "capital" */
    if (!bg_quiz_pat_match ("cap{ital}", "cap"))     ok = 0;
    if (!bg_quiz_pat_match ("cap{ital}", "capital")) ok = 0;
    if (bg_quiz_pat_match ("cap{ital}", "capit"))    ok = 0;

    /* alternation: a|b matches either */
    if (!bg_quiz_pat_match ("yes|no", "yes")) ok = 0;
    if (!bg_quiz_pat_match ("yes|no", "no"))  ok = 0;
    if (bg_quiz_pat_match ("yes|no", "maybe")) ok = 0;

    /* group with alternation + suffix */
    if (!bg_quiz_pat_match ("[a|b]c", "ac")) ok = 0;
    if (!bg_quiz_pat_match ("[a|b]c", "bc")) ok = 0;
    if (bg_quiz_pat_match ("[a|b]c", "cc"))  ok = 0;

    /* case-insensitive */
    if (!bg_quiz_pat_match ("Paris", "paris")) ok = 0;

    /* expansion picks the first alternative; optional taken as its body */
    bg_quiz_pat_expand ("cap{ital}", buf, sizeof buf);
    if (strcmp (buf, "capital") != 0) ok = 0;
    bg_quiz_pat_expand ("yes|no", buf, sizeof buf);
    if (strcmp (buf, "yes") != 0) ok = 0;
    bg_quiz_pat_expand ("country", buf, sizeof buf);
    if (strcmp (buf, "country") != 0) ok = 0;

    /* seeded PRNG is reproducible */
    {
        int a, b;
        bg_quiz_seed (12345);
        a = bg_quiz_rnd (1000);
        bg_quiz_seed (12345);
        b = bg_quiz_rnd (1000);
        if (a != b) ok = 0;
    }

    /* split honors escaped colons */
    {
        char st[64];
        char *f[BG_QUIZ_MAXFIELDS];
        int n = bg_quiz_split ("a\\:b:c", st, sizeof st, f, BG_QUIZ_MAXFIELDS);
        if (n != 2) ok = 0;
    }

    printf ("quiz selftest: %s\n", ok ? "ok" : "FAIL");
    return ok ? 0 : 1;
}

/* ---- entry point -------------------------------------------------------- */
static int bsdg_quiz (int argc, char **argv) {
    int seeded = 0;
    uint64_t seed = 0;
    long rounds = -1;             /* -1 = all rows */
    const char *datafile = 0;
    const char *catname = 0;      /* --category NAME selects an index entry */
    int do_list = 0;
    const char *pos[2] = { 0, 0 };
    int npos = 0;
    int i;

    if (!datafile) {
        const char *env = getenv ("QUIZ_DATA");
        if (env && *env)
            datafile = env;
    }

    for (i = 0; i < argc; i++) {
        const char *a = argv[i];

        if (strcmp (a, "--help") == 0 || strcmp (a, "-h") == 0)
            return bg_quiz_usage (stdout, 0);
        if (strcmp (a, "--selftest") == 0)
            return bg_quiz_selftest ();
        if (strcmp (a, "--list") == 0) {
            do_list = 1;
            continue;
        }
        if (strcmp (a, "--seed") == 0) {
            char *ep;
            if (i + 1 >= argc) {
                fputs ("quiz: --seed requires an argument\n", stderr);
                return bg_quiz_usage (stderr, 2);
            }
            seed = (uint64_t) strtoull (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i])
                return bg_quiz_usage (stderr, 2);
            seeded = 1;
            continue;
        }
        if (strcmp (a, "--rounds") == 0) {
            char *ep;
            if (i + 1 >= argc) {
                fputs ("quiz: --rounds requires an argument\n", stderr);
                return bg_quiz_usage (stderr, 2);
            }
            rounds = strtol (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i] || rounds < 0)
                return bg_quiz_usage (stderr, 2);
            continue;
        }
        if (strcmp (a, "-i") == 0 || strcmp (a, "--data") == 0) {
            if (i + 1 >= argc) {
                fputs ("quiz: -i requires a file argument\n", stderr);
                return bg_quiz_usage (stderr, 2);
            }
            datafile = argv[++i];
            continue;
        }
        if (strcmp (a, "--category") == 0) {
            if (i + 1 >= argc) {
                fputs ("quiz: --category requires an argument\n", stderr);
                return bg_quiz_usage (stderr, 2);
            }
            catname = argv[++i];
            continue;
        }
        if (a[0] == '-' && a[1] != '\0') {
            /* unknown option */
            return bg_quiz_usage (stderr, 2);
        }
        /* positional category argument */
        if (npos < 2)
            pos[npos++] = a;
        else
            return bg_quiz_usage (stderr, 2);
    }

    if (seeded)
        bg_quiz_seed (seed);
    else
        bg_quiz_seed ((uint64_t) time (NULL) ^ (uint64_t) getpid ());

    /* ---- explicit data file path: load an index, then select a pair ---- */
    if (datafile) {
        int nidx;
        char **idx = bg_quiz_read_lines (datafile, &nidx);
        char dirbuf[BG_QUIZ_LINE_SZ];
        const char *slash;
        int rc = 1;

        if (!idx) {
            fprintf (stderr, "quiz: cannot open %s\n", datafile);
            return 1;
        }
        /* directory of the index file, for resolving relative data paths */
        dirbuf[0] = '\0';
        slash = strrchr (datafile, '/');
        if (slash) {
            size_t dl = (size_t) (slash - datafile + 1);
            if (dl < sizeof dirbuf) {
                memcpy (dirbuf, datafile, dl);
                dirbuf[dl] = '\0';
            }
        }

        if (do_list || (npos < 2 && !catname)) {
            int k;
            printf ("Subjects:\n\n");
            for (k = 0; k < nidx; ++k) {
                const char *colon = strchr (idx[k], ':');
                if (colon)
                    bg_quiz_print_index_line (colon + 1);
            }
            printf ("\nType two category names to start, e.g. the first two "
                    "shown on a line.\nType an empty line to get the correct "
                    "answer.\n");
            bg_quiz_free_lines (idx, nidx);
            return 0;
        }

        {
            int k, qi = 0, ai = 0;
            const char *c1 = pos[0], *c2 = pos[1];
            char lc1[128], lc2[128];
            if (npos < 2) {
                fputs ("quiz: need two category names\n", stderr);
                bg_quiz_free_lines (idx, nidx);
                return bg_quiz_usage (stderr, 2);
            }
            strncpy (lc1, c1, sizeof lc1 - 1); lc1[sizeof lc1 - 1] = '\0';
            strncpy (lc2, c2, sizeof lc2 - 1); lc2[sizeof lc2 - 1] = '\0';
            bg_quiz_downcase (lc1);
            bg_quiz_downcase (lc2);

            for (k = 0; k < nidx; ++k) {
                const char *colon = strchr (idx[k], ':');
                char pathpart[BG_QUIZ_LINE_SZ];
                size_t pl;
                if (!colon)
                    continue;
                pl = (size_t) (colon - idx[k]);
                if (pl >= sizeof pathpart)
                    pl = sizeof pathpart - 1;
                memcpy (pathpart, idx[k], pl);
                pathpart[pl] = '\0';

                if (bg_quiz_match_cats (colon + 1, lc1, lc2, &qi, &ai)) {
                    /* resolve data path: strip @...@/ placeholder dir, then
                     * join with the index file's directory if relative. */
                    char resolved[BG_QUIZ_LINE_SZ];
                    const char *base = pathpart;
                    const char *bslash = strrchr (pathpart, '/');
                    int drows;
                    char **rows;
                    bg_quiz_cat cat;

                    if (bslash)
                        base = bslash + 1;
                    if (pathpart[0] == '/')
                        snprintf (resolved, sizeof resolved, "%s", pathpart);
                    else
                        snprintf (resolved, sizeof resolved, "%s%s",
                                  dirbuf, base);

                    rows = bg_quiz_read_lines (resolved, &drows);
                    if (!rows) {
                        fprintf (stderr, "quiz: cannot open data %s\n",
                                 resolved);
                        rc = 1;
                        break;
                    }
                    memset (&cat, 0, sizeof cat);
                    strncpy (cat.names, colon + 1, sizeof cat.names - 1);
                    cat.names[sizeof cat.names - 1] = '\0';
                    cat.nnames = bg_quiz_split (cat.names, cat.names,
                                                sizeof cat.names, cat.namefld,
                                                BG_QUIZ_MAXFIELDS);
                    cat.rows = rows;
                    cat.nrows = drows;
                    cat.rows_owned = 1;
                    rc = bg_quiz_run (&cat, qi, ai, rounds, stdin);
                    bg_quiz_cat_free (&cat);
                    bg_quiz_free_lines (idx, nidx);
                    return rc;
                }
            }
            fputs ("quiz: invalid categories\n", stderr);
            bg_quiz_free_lines (idx, nidx);
            return 1;
        }
    }

    /* ---- embedded categories ------------------------------------------- */
    if (do_list || (npos < 2 && !catname)) {
        bg_quiz_show_embedded_index ();
        return 0;
    }

    {
        bg_quiz_cat cap, ele;
        int qi = 0, ai = 0;
        char lc1[128], lc2[128];
        const char *c1, *c2;

        bg_quiz_cat_init (&cap, bg_quiz_capitals_names, bg_quiz_capitals_rows);
        bg_quiz_cat_init (&ele, bg_quiz_elements_names, bg_quiz_elements_rows);

        /* --category NAME: shorthand selecting an embedded set by its first
         * field/category name, asking field 0 -> field 1. */
        if (catname && npos < 2) {
            char lcn[128];
            strncpy (lcn, catname, sizeof lcn - 1); lcn[sizeof lcn - 1] = '\0';
            bg_quiz_downcase (lcn);
            if (strcmp (lcn, "capitals") == 0 || strcmp (lcn, "capital") == 0
                || strcmp (lcn, "country") == 0) {
                return bg_quiz_run (&cap, 0, 1, rounds, stdin);
            }
            if (strcmp (lcn, "elements") == 0 || strcmp (lcn, "element") == 0
                || strcmp (lcn, "symbol") == 0) {
                return bg_quiz_run (&ele, 3, 0, rounds, stdin); /* name->symbol */
            }
            fputs ("quiz: unknown category\n", stderr);
            return 1;
        }

        c1 = pos[0];
        c2 = pos[1];
        strncpy (lc1, c1, sizeof lc1 - 1); lc1[sizeof lc1 - 1] = '\0';
        strncpy (lc2, c2, sizeof lc2 - 1); lc2[sizeof lc2 - 1] = '\0';
        bg_quiz_downcase (lc1);
        bg_quiz_downcase (lc2);

        if (bg_quiz_match_cats (bg_quiz_capitals_names, lc1, lc2, &qi, &ai))
            return bg_quiz_run (&cap, qi, ai, rounds, stdin);
        if (bg_quiz_match_cats (bg_quiz_elements_names, lc1, lc2, &qi, &ai))
            return bg_quiz_run (&ele, qi, ai, rounds, stdin);

        fputs ("quiz: invalid categories\n", stderr);
        return 1;
    }
}

/* ===== rain.c ===== */
/* @game rain : animated falling-raindrops terminal effect (ANSI, no curses) */
/* bsdgames `rain`: the classic VAX/VMS-style raindrop animation. A new drop
 * lands at a random cell each tick; the four previously-landed drops age
 * through a fixed splash sequence ('.', then 'o', then 'O', then a '|.|'
 * ring, then a larger '/ \ | O | \ /' ring, then erased), exactly like the
 * NetBSD rain(6) which keeps a 5-deep ring buffer of recent drop positions.
 *
 * No curses: cursor motion and screen clears are emitted as raw ANSI escapes
 * (CUP "ESC[row;colH", clear "ESC[2J", home "ESC[H", hide/show cursor
 * "ESC[?25l"/"ESC[?25h"). Raw-terminal/animation behavior is gated on
 * isatty(1): with a tty and no bound, it loops forever with a delay and
 * installs SIGINT/SIGTERM/SIGHUP handlers that show the cursor and reset the
 * terminal before exiting 0.
 *
 * Bounded, deterministic, headless paths for tests (never block, no real TTY
 * needed):
 *   --frames N   render exactly N frames (ANSI escapes to stdout), exit 0.
 *   --selftest   run an internal geometry/PRNG check, print one stable line
 *                ("rain: selftest ok ...") and exit 0.
 *   --seed N     seed the internal xorshift PRNG (default fixed) so frame
 *                output is fully deterministic.
 *   --cols C / --lines L   pin the field size (default from $COLUMNS/$LINES
 *                or 80x24) so tests do not depend on a real terminal size.
 *   -d MS        per-frame delay in milliseconds (1-999), like rain(6).
 *   --help / -h  usage to stdout, exit 0.
 *
 * No state/score files, no stdin use. Adapter spliced into bsdgames.c
 * (which provides the includes); all symbols static + bg_rain_-prefixed.
 *
 * Needs <signal.h> for the interactive restore handlers (declared below
 * without an #include, per the no-include adapter contract). */

/* ---- minimal libc decls not in the shared header set ---------------------
 * The host splice provides <stdio.h> <stdlib.h> <string.h> <ctype.h>
 * <stdint.h> <time.h> <unistd.h>. We additionally use signal() and usleep().
 * Rather than add #include lines (forbidden by the contract) we forward-
 * declare exactly what we touch; these match the glibc/musl prototypes. */
typedef void (*bg_rain_sigh)(int);
extern bg_rain_sigh signal(int, bg_rain_sigh);
extern int usleep(unsigned int);
#ifndef SIGHUP
#define SIGHUP  1
#endif
#ifndef SIGINT
#define SIGINT  2
#endif
#ifndef SIGTERM
#define SIGTERM 15
#endif

/* ANSI control strings. */
#define BG_RAIN_CLR   "\033[2J"     /* clear entire screen           */
#define BG_RAIN_HOME  "\033[H"      /* cursor to row 1, col 1        */
#define BG_RAIN_HIDE  "\033[?25l"   /* hide cursor                   */
#define BG_RAIN_SHOW  "\033[?25h"   /* show cursor                   */

/* Set by the signal handler during the interactive (tty) loop. */
static volatile int bg_rain_sig_caught = 0;

static void bg_rain_onsig(int dummy) {
    (void)dummy;
    bg_rain_sig_caught = 1;
}

/* Deterministic xorshift32 PRNG (seedable). Seeded from a fixed default so
 * --frames output is reproducible; --seed N overrides it. */
static uint32_t bg_rain_rng = 0x9e3779b9u;
static void bg_rain_srand(uint32_t s) {
    bg_rain_rng = s ? s : 0x9e3779b9u;   /* avoid the zero fixed point */
}
static uint32_t bg_rain_rand(void) {
    uint32_t x = bg_rain_rng;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    bg_rain_rng = x;
    return x;
}

/* Move the cursor to (row r, col c). The original uses 0-based curses coords;
 * ANSI CUP is 1-based, so we add 1. Negative/oversized coords are clamped to
 * the visible region by the caller's geometry, but we guard >=1 here too. */
static void bg_rain_move(int r, int c) {
    if (r < 1) r = 1;
    if (c < 1) c = 1;
    printf("\033[%d;%dH", r, c);
}

/* Emit a single character at curses-coords (y, x) (0-based, like the oracle).
 * ANSI is 1-based so we render at (y+1, x+1). */
static void bg_rain_addch(int y, int x, int ch) {
    bg_rain_move(y + 1, x + 1);
    putchar(ch);
}

/* Emit a NUL-terminated string starting at curses-coords (y, x). */
static void bg_rain_addstr(int y, int x, const char *s) {
    bg_rain_move(y + 1, x + 1);
    fputs(s, stdout);
}

/* Render the full ageing splash for the ring of recent drop positions, given
 * the current head index j. This mirrors the NetBSD rain inner loop: each
 * stage walks one slot further back in the 5-deep ring (wrapping at 0->4) and
 * draws that drop one stage older. Returns nothing; writes ANSI to stdout. */
static void bg_rain_splash(const int *xpos, const int *ypos, int j,
                           int newx, int newy) {
    /* Newest landing point. */
    bg_rain_addch(newy, newx, '.');

    bg_rain_addch(ypos[j], xpos[j], 'o');
    if (!j--) j = 4;

    bg_rain_addch(ypos[j], xpos[j], 'O');
    if (!j--) j = 4;

    bg_rain_addch(ypos[j] - 1, xpos[j], '-');
    bg_rain_addstr(ypos[j], xpos[j] - 1, "|.|");
    bg_rain_addch(ypos[j] + 1, xpos[j], '-');
    if (!j--) j = 4;

    bg_rain_addch(ypos[j] - 2, xpos[j], '-');
    bg_rain_addstr(ypos[j] - 1, xpos[j] - 1, "/ \\");
    bg_rain_addstr(ypos[j], xpos[j] - 2, "| O |");
    bg_rain_addstr(ypos[j] + 1, xpos[j] - 1, "\\ /");
    bg_rain_addch(ypos[j] + 2, xpos[j], '-');
    if (!j--) j = 4;

    /* Oldest stage: erase the big ring so the field stays clean. */
    bg_rain_addch(ypos[j] - 2, xpos[j], ' ');
    bg_rain_addstr(ypos[j] - 1, xpos[j] - 1, "   ");
    bg_rain_addstr(ypos[j], xpos[j] - 2, "     ");
    bg_rain_addstr(ypos[j] + 1, xpos[j] - 1, "   ");
    bg_rain_addch(ypos[j] + 2, xpos[j], ' ');
}

/* Parse a base-10 non-negative int from s into *out. Returns 0 on success,
 * -1 if s is empty or has trailing junk. */
static int bg_rain_parse_int(const char *s, long *out) {
    char *ep;
    long v;
    if (!s || !*s) return -1;
    v = strtol(s, &ep, 10);
    if (ep == s || *ep) return -1;
    *out = v;
    return 0;
}

static int bsdg_rain(int argc, char **argv) {
    long frames = -1;           /* <0 means unbounded (interactive)        */
    long want_seed = 0;         /* --seed N (0 -> use the fixed default)   */
    int  have_seed = 0;
    long cols_arg = -1, lines_arg = -1;
    unsigned int delay = 120000; /* default 120 ms, like rain(6)           */
    int  selftest = 0;
    int  i;
    int  cols, lines;
    int  x, y, j;
    int  xpos[5], ypos[5];

    /* ---- argument parsing (adapter flags + the historical -d) ---------- */
    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "--help") == 0 || strcmp(a, "-h") == 0) {
            fputs("usage: rain [-d delay_ms] [--frames N] [--seed N] "
                  "[--cols C] [--lines L] [--selftest]\n", stdout);
            return 0;
        } else if (strcmp(a, "--selftest") == 0) {
            selftest = 1;
        } else if (strcmp(a, "--frames") == 0) {
            long v;
            if (i + 1 >= argc || bg_rain_parse_int(argv[++i], &v) < 0 || v < 0) {
                fputs("rain: --frames needs a non-negative count\n", stderr);
                return 2;
            }
            frames = v;
        } else if (strcmp(a, "--seed") == 0) {
            long v;
            if (i + 1 >= argc || bg_rain_parse_int(argv[++i], &v) < 0) {
                fputs("rain: --seed needs an integer\n", stderr);
                return 2;
            }
            want_seed = v; have_seed = 1;
        } else if (strcmp(a, "--cols") == 0) {
            long v;
            if (i + 1 >= argc || bg_rain_parse_int(argv[++i], &v) < 0 || v < 9) {
                fputs("rain: --cols needs an integer >= 9\n", stderr);
                return 2;
            }
            cols_arg = v;
        } else if (strcmp(a, "--lines") == 0) {
            long v;
            if (i + 1 >= argc || bg_rain_parse_int(argv[++i], &v) < 0 || v < 9) {
                fputs("rain: --lines needs an integer >= 9\n", stderr);
                return 2;
            }
            lines_arg = v;
        } else if (strcmp(a, "-d") == 0) {
            long v;
            if (i + 1 >= argc || bg_rain_parse_int(argv[++i], &v) < 0 ||
                v < 1 || v >= 1000) {
                fputs("rain: invalid delay (1-999)\n", stderr);
                return 2;
            }
            delay = (unsigned int)v * 1000u;   /* ms -> us */
        } else {
            fprintf(stderr, "rain: unknown option: %s\n", a);
            return 2;
        }
    }

    bg_rain_srand(have_seed ? (uint32_t)want_seed : 0x9e3779b9u);

    /* ---- field geometry ------------------------------------------------ */
    /* Match rain(6): the usable field is COLS-4 x LINES-4 with drops kept
     * 2 cells in from the edge so the splash never wraps. Size comes from
     * --cols/--lines, else $COLUMNS/$LINES, else an 80x24 default. */
    {
        long c = 80, l = 24;
        const char *e;
        if (cols_arg > 0)       c = cols_arg;
        else if ((e = getenv("COLUMNS")) && bg_rain_parse_int(e, &c) == 0 && c > 0) ;
        else                    c = 80;
        if (lines_arg > 0)      l = lines_arg;
        else if ((e = getenv("LINES")) && bg_rain_parse_int(e, &l) == 0 && l > 0) ;
        else                    l = 24;
        if (c < 9)  c = 9;      /* keep COLS-4 >= 5 for modulo + margin   */
        if (l < 9)  l = 9;
        cols  = (int)c - 4;
        lines = (int)l - 4;
    }

    /* ---- selftest: deterministic, no terminal, one stable line --------- */
    if (selftest) {
        /* Verify the ring ages without ever stepping outside the field and
         * that the PRNG is reproducible from a fixed seed. */
        int k, ok = 1;
        uint32_t a, b;
        bg_rain_srand(12345u);
        a = bg_rain_rand();
        bg_rain_srand(12345u);
        b = bg_rain_rand();
        if (a != b) ok = 0;                 /* PRNG must be reproducible    */
        for (k = 0; k < 5; k++) {
            int px = (int)(bg_rain_rand() % (uint32_t)cols) + 2;
            int py = (int)(bg_rain_rand() % (uint32_t)lines) + 2;
            /* Splash extents are +-2 rows / +-2 cols around (py,px), in
             * curses 0-based coords. On-screen means [0, COLS-1] x
             * [0, LINES-1]; COLS = cols+4, LINES = lines+4. (Like rain(6),
             * the leftmost splash cell can sit at column 0.) */
            if (px - 2 < 0 || px + 2 > cols + 3) ok = 0;
            if (py - 2 < 0 || py + 2 > lines + 3) ok = 0;
        }
        printf("rain: selftest %s field=%dx%d\n",
               ok ? "ok" : "FAIL", cols + 4, lines + 4);
        fflush(stdout);
        return ok ? 0 : 1;
    }

    /* ---- decide interactive vs bounded --------------------------------- */
    /* Interactive only when stdout is a real TTY *and* no frame bound was
     * requested. Otherwise we run the bounded, non-blocking renderer. A
     * non-TTY with no --frames renders a single frame (safe, never blocks). */
    {
        int interactive = isatty(1) && frames < 0;
        long limit;
        int restore = 0;

        if (interactive) {
            /* Long but finite ceiling so even the interactive path cannot
             * run unbounded inside a harness that fakes a tty; a real user
             * Ctrl-C's out via the signal handler well before this. */
            limit = 1000000000L;
            signal(SIGHUP,  bg_rain_onsig);
            signal(SIGINT,  bg_rain_onsig);
            signal(SIGTERM, bg_rain_onsig);
            fputs(BG_RAIN_HIDE, stdout);
            fputs(BG_RAIN_CLR,  stdout);
            restore = 1;
        } else {
            limit = (frames < 0) ? 1 : frames;   /* non-tty default = 1     */
            /* Clear once so a captured frame is self-contained. */
            if (limit > 0) fputs(BG_RAIN_CLR, stdout);
        }

        /* Seed the ring with starting positions (oracle order: j=4..0). */
        for (j = 4; j >= 0; --j) {
            xpos[j] = (int)(bg_rain_rand() % (uint32_t)cols) + 2;
            ypos[j] = (int)(bg_rain_rand() % (uint32_t)lines) + 2;
        }

        j = 0;
        for (long f = 0; f < limit; f++) {
            if (interactive && bg_rain_sig_caught)
                break;

            x = (int)(bg_rain_rand() % (uint32_t)cols) + 2;
            y = (int)(bg_rain_rand() % (uint32_t)lines) + 2;

            bg_rain_splash(xpos, ypos, j, x, y);

            /* Advance the ring head exactly as the oracle does (it has
             * decremented j four times inside splash; recompute the new
             * head and store the fresh landing). */
            {
                int jj = j;
                int s;
                for (s = 0; s < 4; s++) { if (!jj--) jj = 4; }
                xpos[jj] = x;
                ypos[jj] = y;
                j = jj;
            }

            /* Park the cursor out of the way and flush this frame. */
            bg_rain_move(lines + 4, cols + 4);
            fflush(stdout);

            if (interactive && delay)
                usleep(delay);
        }

        if (restore) {
            fputs(BG_RAIN_SHOW, stdout);
            fputs(BG_RAIN_HOME, stdout);
            fflush(stdout);
        }
    }

    return 0;
}

/* ===== random.c ===== */
/* @game random : copy stdin to stdout, printing each line with prob 1/denom */
/* bsdgames `random` filter. Reads lines from stdin and copies them to stdout
 * with a probability of 1/denominator (the default denominator is 2). With
 * `-e` it reads/writes nothing and returns a random exit status in
 * [0, denominator). `-r` requests unbuffered output (we already emit byte by
 * byte, so it is honored by disabling stdio buffering). An optional positional
 * `denominator` (a positive integer; the original accepts a double, we take a
 * non-negative integer >= 1) follows the options.
 *
 * The historical /usr/games/random seeds from gettimeofday()+getpid() and uses
 * random(); to keep tests deterministic this adapter uses a private, static,
 * seeded 64-bit xorshift PRNG. With no `--seed` it is seeded from
 * time(NULL) ^ getpid() (non-deterministic, like the original). `--seed N`
 * pins the stream so a fixed seed + denominator yields stable output / exit
 * status. The per-line draw cadence mirrors the original: one draw primes the
 * first line, then one draw after each newline decides the next line, so
 * line selections are independent 1/denom Bernoulli trials.
 *
 * `--help`/`-h` as the first operand prints a usage line to stdout and exits 0
 * (the original printed usage to stderr and exited 1). Stdout-only, no state,
 * no terminal raw mode. Adapter spliced into bsdgames.c (which provides the
 * includes); all symbols static + bg_random_-prefixed. */

/* 64-bit xorshift state for this adapter only. */
static uint64_t bg_random_state = 0x9e3779b97f4a7c15ULL;

static void bg_random_seed (uint64_t s) {
    /* Avoid the all-zero fixed point of xorshift; splitmix the seed in. */
    s ^= 0x9e3779b97f4a7c15ULL;
    s = (s ^ (s >> 30)) * 0xbf58476d1ce4e5b9ULL;
    s = (s ^ (s >> 27)) * 0x94d049bb133111ebULL;
    s ^= s >> 31;
    if (s == 0)
        s = 0x9e3779b97f4a7c15ULL;
    bg_random_state = s;
}

static uint64_t bg_random_next (void) {
    uint64_t x = bg_random_state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    bg_random_state = x;
    return x;
}

/* Return 1 with probability 1/denom (denom >= 1): draw is "selected" when
 * (draw mod denom) == 0, matching the original's 0-of-denom test. */
static int bg_random_selected (long denom) {
    return (long)(bg_random_next () % (uint64_t) denom) == 0;
}

static int bg_random_usage (FILE *out, int rc) {
    fputs ("usage: random [-er] [--seed N] [denominator]\n", out);
    return rc;
}

static int bsdg_random (int argc, char **argv) {
    long denom = 2;
    int random_exit = 0, unbuffer_output = 0;
    int seeded = 0;
    uint64_t seed = 0;
    int i = 0;
    int got_denom = 0;
    int c;

    /* Parse options. We accept clustered short flags like the original getopt
     * "er", plus the adapter-only long option --seed N and --help/-h. The
     * single positional operand is the denominator. */
    for (; i < argc; i++) {
        const char *a = argv[i];

        if (strcmp (a, "--help") == 0 || strcmp (a, "-h") == 0)
            return bg_random_usage (stdout, 0);

        if (strcmp (a, "--seed") == 0) {
            char *ep;
            if (i + 1 >= argc) {
                fputs ("random: --seed requires an argument\n", stderr);
                return bg_random_usage (stderr, 2);
            }
            seed = (uint64_t) strtoull (argv[++i], &ep, 10);
            if (*ep != '\0' || ep == argv[i]) {
                fprintf (stderr, "random: invalid seed: %s\n", argv[i]);
                return 2;
            }
            seeded = 1;
            continue;
        }

        if (a[0] == '-' && a[1] != '\0') {
            const char *p = a + 1;
            for (; *p; p++) {
                if (*p == 'e')
                    random_exit = 1;
                else if (*p == 'r')
                    unbuffer_output = 1;
                else
                    return bg_random_usage (stderr, 2);
            }
            continue;
        }

        /* Positional: the denominator. Only one is allowed. */
        if (got_denom)
            return bg_random_usage (stderr, 2);
        {
            char *ep;
            denom = strtol (a, &ep, 10);
            if (*ep != '\0' || ep == a || denom < 1) {
                fputs ("random: denominator is not valid.\n", stderr);
                return 1;
            }
            got_denom = 1;
        }
    }

    if (seeded)
        bg_random_seed (seed);
    else
        bg_random_seed ((uint64_t) time (NULL) ^ (uint64_t) getpid ());

    /* -e: emit nothing, return a random exit status in [0, denom). */
    if (random_exit)
        return (int) (bg_random_next () % (uint64_t) denom);

    if (unbuffer_output)
        setbuf (stdout, NULL);

    /* Filter mode: prime the first line, then re-decide after each newline. */
    {
        int selected = bg_random_selected (denom);
        while ((c = getchar ()) != EOF) {
            if (selected)
                putchar (c);
            if (c == '\n')
                selected = bg_random_selected (denom);
        }
    }
    return 0;
}

/* ===== robots.c ===== */
/* @game robots : flee the robots on a grid; they crash into each other and junk heaps */
/* bsdgames `robots` (UCB). You are '@' on a boxed field; '+' robots all step one
 * cell toward you every turn. Two robots that step onto the same cell (or onto an
 * existing junk heap '*') collide and fuse into a junk heap, scoring 10 points
 * each. A robot that reaches your cell kills you. Clear every robot on the level
 * to advance; survive and your score carries on. You may move one of the eight
 * compass directions (y k u / h l / b j n, vi-style diagonals), wait in place
 * ('.'/space), wait out the level ('w'), or teleport to a random cell ('t').
 *
 * Faithful to the oracle's mechanics: field interior is 22 rows x 59 cols (the
 * NetBSD Y_FIELDSIZE-1 x X_FIELDSIZE-1 playable area); a robot steps by the sign
 * of (player - robot) on each axis; a cell occupied by >1 robot becomes a heap
 * and removes those robots; a heap is permanent terrain that further robots crash
 * into. eaten()/must_telep() use the same "a neighbour holds exactly one live
 * robot" rule, and a move is rejected if the destination holds anything (robot or
 * heap) or would step adjacent to a live robot. Level L spawns min(L*10, 40)
 * robots. Scoring is 10 per scrapped robot plus the advance/wait bonuses.
 *
 * No curses. The interactive renderer (gated on isatty(0)) puts the terminal in
 * raw mode, draws the field with plain ANSI, reads single keystrokes, and on
 * SIGINT/SIGTERM/SIGHUP restores cooked mode (cursor shown) before exiting, so
 * the terminal is never left wedged.
 *
 * Bounded, deterministic, headless paths for tests (never block, no real TTY):
 *   moves on stdin   when stdin is not a TTY, move keys are read one byte at a
 *                    time and the game stops at EOF. A captured transcript is
 *                    fully reproducible.
 *   --seed N         seed the internal xorshift PRNG that places robots and the
 *                    player, so a level is identical on every run. Without it the
 *                    seed comes from $BASH_BSDGAMES_SEED if set, else clock^pid.
 *   --level N        start on level N (1..4 like robots -a); also sets how many
 *                    robots spawn. Default 1.
 *   --quiet          suppress the per-move board frames (only status/score lines
 *                    are printed); handy for scripted comparisons.
 *   --selftest       run internal placement/chase/collision/score checks, print a
 *                    stable line ("robots: selftest ok"), exit 0.
 *   --help / -h      usage to stdout, exit 0.
 *
 * No state/score files (the IMPL plan calls for --no-score by default and this
 * adapter never writes one). Adapter spliced into bsdgames.c (which provides
 * the includes); all symbols static and bg_robots_-prefixed. Plain ints are
 * returned (0 ok / 1 fail / 2 usage) and messages go to stderr, so the file also
 * passes the isolated compile-check harness that lacks loadables.h. */

/* ---- field geometry (mirror robots.h) ----------------------------------- */
#define BG_ROBOTS_YFS   23      /* Y_FIELDSIZE: rows are 1..YFS-1 playable     */
#define BG_ROBOTS_XFS   60      /* X_FIELDSIZE: cols are 1..XFS-1 playable     */
#define BG_ROBOTS_MAXLEVELS 4
#define BG_ROBOTS_MAXROBOTS (BG_ROBOTS_MAXLEVELS * 10)   /* 40                 */
#define BG_ROBOTS_ROB_SCORE 10
#define BG_ROBOTS_S_BONUS   (60 * BG_ROBOTS_ROB_SCORE)   /* advance bonus      */

#define BG_ROBOTS_ROBOT '+'
#define BG_ROBOTS_HEAP  '*'
#define BG_ROBOTS_PLAYER '@'

/* ANSI control strings for the interactive path. */
#define BG_ROBOTS_CLR   "\033[2J"
#define BG_ROBOTS_HOME  "\033[H"
#define BG_ROBOTS_HIDE  "\033[?25l"
#define BG_ROBOTS_SHOW  "\033[?25h"

/* Bound on scripted turns so a hostile transcript can never spin forever. */
#define BG_ROBOTS_MAXTURNS 100000

/* ---- signal-number fallbacks ------------------------------------------- */
/* The host splice provides <stdio.h> <stdlib.h> <string.h> <ctype.h>
 * <stdint.h> <unistd.h> <time.h> <signal.h> <termios.h> <poll.h>
 * <sys/time.h> <math.h>, so usleep()/poll()/termios/etc. are all in scope
 * with no extra declarations. These guarded fallbacks only define the signal
 * numbers if <signal.h> somehow did not (it always does on Linux). */
#ifndef SIGHUP
#define SIGHUP  1
#endif
#ifndef SIGINT
#define SIGINT  2
#endif
#ifndef SIGTERM
#define SIGTERM 15
#endif

/* ---- deterministic PRNG (xorshift32, seedable) -------------------------- */
static uint32_t bg_robots_rng = 0x9e3779b9u;
static void bg_robots_srand(uint32_t s) {
    bg_robots_rng = s ? s : 0x9e3779b9u;   /* avoid the zero fixed point */
}
static uint32_t bg_robots_rand(void) {
    uint32_t x = bg_robots_rng;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    bg_robots_rng = x;
    return x;
}
/* Value in [0, range); mirrors robots' rnd(range) == rand() % range. */
static int bg_robots_rnd(int range) {
    if (range <= 0) return 0;
    return (int)(bg_robots_rand() % (uint32_t)range);
}

/* ---- game state --------------------------------------------------------- */
typedef struct { int y, x; } bg_robots_coord;

typedef struct {
    /* Field[y][x] is a count of robots on that cell; a junk heap is recorded as
     * a separate boolean overlay so we can keep both the live-robot count and
     * the permanent heap terrain straight (the oracle leaves the heap count in
     * Field, but tracking heaps explicitly is clearer and behaves identically
     * for the >0 "blocked" and ==1 "eaten" tests). */
    signed char field[BG_ROBOTS_YFS][BG_ROBOTS_XFS];  /* live robots per cell  */
    unsigned char heap[BG_ROBOTS_YFS][BG_ROBOTS_XFS];  /* 1 = junk heap         */
    bg_robots_coord robots[BG_ROBOTS_MAXROBOTS];       /* live robots (y<0 dead)*/
    bg_robots_coord me;                                /* player position       */
    int num_robots;          /* live robots remaining on the level             */
    int level;               /* current level                                  */
    int start_level;         /* level the game started on (for advance bonus)  */
    long score;              /* accumulated score                              */
    int dead;                /* player has been caught                         */
    int waiting;             /* player chose to wait out the level             */
    int wait_bonus;          /* robots scrapped while waiting (bonus points)   */
} bg_robots_game;

static int bg_robots_sign(int n) { return n < 0 ? -1 : (n > 0 ? 1 : 0); }

/* On-field test: a cell holds "stuff" the player cannot move onto. */
static int bg_robots_blocked(const bg_robots_game *g, int y, int x) {
    return g->field[y][x] > 0 || g->heap[y][x];
}

/* eaten(pos): the player would be eaten standing at (y,x) if any of the eight
 * neighbours (in bounds) holds at least one live robot. Mirrors move.c eaten(),
 * which tests Field[y][x] == 1; since a heap is not a live robot it never
 * "eats", and a cell with >1 robot only exists transiently mid-collision. */
static int bg_robots_eaten(const bg_robots_game *g, int y, int x) {
    int dy, dx;
    for (dy = -1; dy <= 1; dy++) {
        int ny = y + dy;
        if (ny <= 0 || ny >= BG_ROBOTS_YFS) continue;
        for (dx = -1; dx <= 1; dx++) {
            int nx = x + dx;
            if (nx <= 0 || nx >= BG_ROBOTS_XFS) continue;
            if (g->field[ny][nx] >= 1) return 1;
        }
    }
    return 0;
}

/* must_telep(): is every reachable neighbour either blocked or fatal, so the
 * only escape is teleport? Mirrors move.c must_telep(). */
static int bg_robots_must_telep(const bg_robots_game *g) {
    int dy, dx;
    for (dy = -1; dy <= 1; dy++) {
        int ny = g->me.y + dy;
        if (ny <= 0 || ny >= BG_ROBOTS_YFS) continue;
        for (dx = -1; dx <= 1; dx++) {
            int nx = g->me.x + dx;
            if (nx <= 0 || nx >= BG_ROBOTS_XFS) continue;
            if (bg_robots_blocked(g, ny, nx)) continue;
            if (!bg_robots_eaten(g, ny, nx)) return 0;
        }
    }
    return 1;
}

/* rnd_pos(): a random unoccupied cell (no live robot and no heap). Bounded so a
 * (theoretically) packed field cannot loop forever; falls back to a linear scan. */
static bg_robots_coord bg_robots_rnd_pos(const bg_robots_game *g) {
    bg_robots_coord p;
    int tries;
    for (tries = 0; tries < 100000; tries++) {
        p.y = bg_robots_rnd(BG_ROBOTS_YFS - 1) + 1;   /* 1..YFS-1 */
        p.x = bg_robots_rnd(BG_ROBOTS_XFS - 1) + 1;   /* 1..XFS-1 */
        if (!bg_robots_blocked(g, p.y, p.x)) return p;
    }
    for (p.y = 1; p.y < BG_ROBOTS_YFS; p.y++)
        for (p.x = 1; p.x < BG_ROBOTS_XFS; p.x++)
            if (!bg_robots_blocked(g, p.y, p.x)) return p;
    p.y = 1; p.x = 1;
    return p;
}

/* make_level(): wipe the field, spawn min(level*10, MAXROBOTS) robots at random
 * unoccupied cells, then place the player. The PRNG draw order matches the
 * oracle: robots for i = N-1 .. 0, then the player last. */
static void bg_robots_make_level(bg_robots_game *g) {
    int i, n;

    g->waiting = 0;
    g->wait_bonus = 0;
    memset(g->field, 0, sizeof g->field);
    memset(g->heap, 0, sizeof g->heap);
    for (i = 0; i < BG_ROBOTS_MAXROBOTS; i++) g->robots[i].y = -1;
    g->me.y = -1;

    n = g->level * 10;
    if (n > BG_ROBOTS_MAXROBOTS) n = BG_ROBOTS_MAXROBOTS;
    g->num_robots = n;
    i = n;
    while (i-- > 0) {
        bg_robots_coord cp = bg_robots_rnd_pos(g);
        g->robots[i] = cp;
        g->field[cp.y][cp.x]++;
    }
    g->me = bg_robots_rnd_pos(g);
}

/* move_robots(): every live robot steps one cell toward the player (sign of the
 * delta on each axis, clamped to the field). Then: a robot on the player's cell
 * kills the player; a cell now holding >1 robot, or any robot that stepped onto
 * an existing heap, fuses into a heap, scoring ROB_SCORE per robot removed.
 *
 * Faithful detail: the oracle decrements Field on the old cell and increments on
 * the new one, then in a second pass converts cells whose count > 1 to heaps
 * (without zeroing the count). We get the identical outcome by: (a) moving every
 * robot and bumping the per-cell count; (b) any robot landing on a pre-existing
 * heap is scrapped immediately onto that heap; (c) any cell with count > 1 turns
 * to a heap and all robots there are scrapped. */
static void bg_robots_move_robots(bg_robots_game *g) {
    int i;
    bg_robots_coord pre = g->me;

    /* (a) step every live robot toward the player, updating the live counts. */
    for (i = 0; i < BG_ROBOTS_MAXROBOTS; i++) {
        bg_robots_coord *rp = &g->robots[i];
        if (rp->y < 0) continue;
        g->field[rp->y][rp->x]--;
        rp->y += bg_robots_sign(pre.y - rp->y);
        rp->x += bg_robots_sign(pre.x - rp->x);
        if (rp->y <= 0) rp->y = 0;                     /* clamp like the oracle */
        else if (rp->y >= BG_ROBOTS_YFS) rp->y = BG_ROBOTS_YFS - 1;
        if (rp->x <= 0) rp->x = 0;
        else if (rp->x >= BG_ROBOTS_XFS) rp->x = BG_ROBOTS_XFS - 1;
        g->field[rp->y][rp->x]++;
    }

    /* (b,c) resolve kills and collisions. */
    for (i = 0; i < BG_ROBOTS_MAXROBOTS; i++) {
        bg_robots_coord *rp = &g->robots[i];
        if (rp->y < 0) continue;
        if (rp->y == pre.y && rp->x == pre.x) {
            g->dead = 1;
            continue;
        }
        if (g->field[rp->y][rp->x] > 1 || g->heap[rp->y][rp->x]) {
            g->heap[rp->y][rp->x] = 1;
            g->field[rp->y][rp->x]--;   /* this robot is gone from the count   */
            rp->y = -1;
            g->num_robots--;
            if (g->waiting) g->wait_bonus++;
            g->score += BG_ROBOTS_ROB_SCORE;
        }
    }
}

/* do_move(dy,dx): try to step the player. Rejects the move (returns 0, no state
 * change) if it leaves the field, lands on a robot/heap, or would be eaten next
 * to a live robot. A no-op (0,0) "wait one tick" returns 1. Mirrors move.c. */
static int bg_robots_do_move(bg_robots_game *g, int dy, int dx) {
    int ny = g->me.y + dy;
    int nx = g->me.x + dx;
    if (ny <= 0 || ny >= BG_ROBOTS_YFS || nx <= 0 || nx >= BG_ROBOTS_XFS ||
        bg_robots_blocked(g, ny, nx) || bg_robots_eaten(g, ny, nx))
        return 0;
    if (dy == 0 && dx == 0) return 1;
    g->me.y = ny;
    g->me.x = nx;
    return 1;
}

/* Teleport the player to a random unoccupied cell (may land you adjacent to a
 * robot -- the oracle's teleport is a genuine gamble). */
static void bg_robots_teleport(bg_robots_game *g) {
    g->me = bg_robots_rnd_pos(g);
}

/* ---- rendering ---------------------------------------------------------- */
/* Draw the boxed field as plain text. Border matches the oracle (corners '+',
 * top/bottom '-', sides '|'). A status line shows level and score. The frame is
 * plain text (no cursor motion) so it captures cleanly in a pipe. */
static void bg_robots_render(const bg_robots_game *g) {
    int y, x;
    char row[BG_ROBOTS_XFS + 2];

    printf("Level: %d   Score: %ld   Robots: %d\n",
           g->level, g->score, g->num_robots);

    /* top border */
    row[0] = '+';
    for (x = 1; x < BG_ROBOTS_XFS; x++) row[x] = '-';
    row[BG_ROBOTS_XFS] = '+';
    row[BG_ROBOTS_XFS + 1] = '\0';
    printf("%s\n", row);

    for (y = 1; y < BG_ROBOTS_YFS; y++) {
        row[0] = '|';
        for (x = 1; x < BG_ROBOTS_XFS; x++) {
            char c = ' ';
            if (g->heap[y][x]) c = BG_ROBOTS_HEAP;
            if (g->field[y][x] > 0) c = BG_ROBOTS_ROBOT;
            if (g->me.y == y && g->me.x == x) c = BG_ROBOTS_PLAYER;
            row[x] = c;
        }
        row[BG_ROBOTS_XFS] = '|';
        row[BG_ROBOTS_XFS + 1] = '\0';
        printf("%s\n", row);
    }

    /* bottom border */
    row[0] = '+';
    for (x = 1; x < BG_ROBOTS_XFS; x++) row[x] = '-';
    row[BG_ROBOTS_XFS] = '+';
    row[BG_ROBOTS_XFS + 1] = '\0';
    printf("%s\n", row);
}

static void bg_robots_render_ansi(const bg_robots_game *g) {
    fputs(BG_ROBOTS_HOME, stdout);
    bg_robots_render(g);
    fflush(stdout);
}

/* ---- end-of-level bonuses (mirror play_level.c) ------------------------- */
/* Award advance + wait bonuses once a level is cleared without dying. */
static void bg_robots_level_bonus(bg_robots_game *g) {
    if (g->dead) return;
    if (g->level == g->start_level && g->start_level > 1)
        g->score += BG_ROBOTS_S_BONUS;
    if (g->wait_bonus != 0)
        g->score += g->wait_bonus;
}

/* ---- terminal raw mode (interactive only) ------------------------------- */
static struct termios bg_robots_saved_tio;
static int bg_robots_tio_active = 0;
static volatile int bg_robots_sig_caught = 0;

static void bg_robots_restore_tty(void) {
    if (bg_robots_tio_active) {
        tcsetattr(0, TCSANOW, &bg_robots_saved_tio);
        bg_robots_tio_active = 0;
    }
    fputs(BG_ROBOTS_SHOW, stdout);
    fflush(stdout);
}

static void bg_robots_onsig(int dummy) {
    (void)dummy;
    bg_robots_sig_caught = 1;
}

static void bg_robots_raw_tty(void) {
    struct termios t;
    if (tcgetattr(0, &bg_robots_saved_tio) != 0) return;
    t = bg_robots_saved_tio;
    t.c_lflag &= ~(unsigned)(ICANON | ECHO);
    t.c_cc[VMIN] = 0;
    t.c_cc[VTIME] = 0;
    if (tcsetattr(0, TCSANOW, &t) == 0)
        bg_robots_tio_active = 1;
}

/* ---- input + key handling ----------------------------------------------- */
/* Translate a key into a player action. Returns:
 *   1  directional move (sets *dy,*dx)
 *   2  wait one tick (.,space): treat as a (0,0) move
 *   3  wait out the level (w/W)
 *   4  teleport (t/T)
 *   0  ignorable key (newline / unknown): no action this byte
 *  -1  quit (q/Q, Ctrl-C, Ctrl-D)
 * Directions follow the oracle's vi-diagonal layout:
 *     y k u      (-1,-1) (-1,0) (-1,+1)
 *     h   l      ( 0,-1)        ( 0,+1)
 *     b j n      (+1,-1) (+1,0) (+1,+1)  */
static int bg_robots_keyact(int ch, int *dy, int *dx) {
    switch (ch) {
    case 'y': *dy = -1; *dx = -1; return 1;
    case 'k': *dy = -1; *dx =  0; return 1;
    case 'u': *dy = -1; *dx =  1; return 1;
    case 'h': *dy =  0; *dx = -1; return 1;
    case 'l': *dy =  0; *dx =  1; return 1;
    case 'b': *dy =  1; *dx = -1; return 1;
    case 'j': *dy =  1; *dx =  0; return 1;
    case 'n': *dy =  1; *dx =  1; return 1;
    case ' ': case '.': return 2;          /* wait one tick (do_move 0,0)      */
    case 'w': case 'W': return 3;          /* wait out the level               */
    case 't': case 'T': return 4;          /* teleport                         */
    case 'q': case 'Q': case 3: case 4:    /* q / ^C / ^D                      */
        return -1;
    default:
        return 0;
    }
}

static int bg_robots_getbyte_stdin(void) {
    int c = getchar();
    return (c == EOF) ? -1 : c;
}

/* Advance the game one full turn given the player's chosen (dy,dx) move (a
 * teleport is encoded by the caller having already relocated the player). After
 * a successful player move the robots all step; the level may clear here. */
static void bg_robots_turn(bg_robots_game *g) {
    /* Stepping onto a cell that a robot will occupy is resolved inside
     * move_robots (player-cell hit -> dead). We also re-check: if the player is
     * already sharing a cell with a robot (shouldn't happen post do_move) die. */
    if (g->field[g->me.y][g->me.x] != 0)
        g->dead = 1;
    if (!g->dead)
        bg_robots_move_robots(g);
}

/* ---- the scripted (headless) game loop ---------------------------------- */
/* Drive the game from stdin bytes until EOF/quit/death. Plays through level
 * clears, awarding bonuses and building the next level, until the player dies or
 * input ends. When !quiet the board is printed at the start of every level and
 * after every applied action so a transcript captures the whole game. */
static int bg_robots_run_scripted(bg_robots_game *g, int quiet) {
    int ch;
    long turns = 0;

    if (!quiet) bg_robots_render(g);

    while (!g->dead && (ch = bg_robots_getbyte_stdin()) != -1) {
        int dy = 0, dx = 0, k, acted = 0;

        if (++turns > BG_ROBOTS_MAXTURNS) break;   /* hard safety bound */

        k = bg_robots_keyact(ch, &dy, &dx);
        if (k < 0) break;                          /* quit */
        if (k == 0) continue;                      /* ignorable (newlines) */

        if (k == 1 || k == 2) {                    /* directional / wait-tick */
            if (!bg_robots_do_move(g, dy, dx))
                continue;                          /* illegal move: no turn */
            bg_robots_turn(g);
            acted = 1;
        } else if (k == 3) {                       /* wait out the level */
            g->waiting = 1;
            while (!g->dead && g->num_robots > 0) {
                bg_robots_turn(g);
                if (++turns > BG_ROBOTS_MAXTURNS) break;
            }
            acted = 1;
        } else if (k == 4) {                       /* teleport */
            bg_robots_teleport(g);
            bg_robots_turn(g);
            acted = 1;
        }

        if (acted && !quiet) bg_robots_render(g);

        /* Level cleared without dying: bonus, advance, render the new level. */
        if (!g->dead && g->num_robots <= 0) {
            bg_robots_level_bonus(g);
            g->level++;
            bg_robots_make_level(g);
            if (!quiet) bg_robots_render(g);
        }
    }

    if (g->dead)
        printf("AARRrrgghhhh....\nYour final score was %ld\n", g->score);
    else
        printf("Your final score was %ld\n", g->score);
    return 0;
}

/* ---- the interactive (raw-tty) game loop -------------------------------- */
static int bg_robots_getbyte_poll(int *got) {
    struct pollfd pfd;
    unsigned char b;
    int n;
    pfd.fd = 0; pfd.events = POLLIN;
    n = poll(&pfd, 1, -1);                  /* robots is turn-based: block */
    if (n <= 0 || !(pfd.revents & POLLIN)) { *got = 0; return 0; }
    n = (int)read(0, &b, 1);
    if (n <= 0) { *got = -1; return 0; }
    *got = 1;
    return b;
}

static int bg_robots_run_interactive(bg_robots_game *g) {
    signal(SIGHUP,  bg_robots_onsig);
    signal(SIGINT,  bg_robots_onsig);
    signal(SIGTERM, bg_robots_onsig);
    bg_robots_raw_tty();
    fputs(BG_ROBOTS_HIDE, stdout);
    fputs(BG_ROBOTS_CLR,  stdout);
    bg_robots_render_ansi(g);

    while (!g->dead && !bg_robots_sig_caught) {
        int dy = 0, dx = 0, k, got = 0, b;
        b = bg_robots_getbyte_poll(&got);
        if (got < 0) break;                 /* EOF on the tty */
        if (got == 0) continue;

        k = bg_robots_keyact(b, &dy, &dx);
        if (k < 0) break;                   /* quit */
        if (k == 0) continue;

        if (k == 1 || k == 2) {
            if (!bg_robots_do_move(g, dy, dx)) continue;
            bg_robots_turn(g);
        } else if (k == 3) {
            g->waiting = 1;
            while (!g->dead && g->num_robots > 0) bg_robots_turn(g);
        } else if (k == 4) {
            bg_robots_teleport(g);
            bg_robots_turn(g);
        }

        bg_robots_render_ansi(g);

        if (!g->dead && g->num_robots <= 0) {
            bg_robots_level_bonus(g);
            g->level++;
            bg_robots_make_level(g);
            bg_robots_render_ansi(g);
        }
    }

    bg_robots_restore_tty();
    fputs(BG_ROBOTS_HOME, stdout);
    if (g->dead)
        printf("\nAARRrrgghhhh....\nYour final score was %ld\n\n", g->score);
    else
        printf("\nYour final score was %ld\n\n", g->score);
    fflush(stdout);
    return 0;
}

/* ---- argument helpers --------------------------------------------------- */
static int bg_robots_parse_int(const char *s, long *out) {
    char *ep;
    long v;
    if (!s || !*s) return -1;
    v = strtol(s, &ep, 10);
    if (ep == s || *ep) return -1;
    *out = v;
    return 0;
}

/* ---- selftest ----------------------------------------------------------- */
/* Zero a game and mark every robot slot dead (y=-1), matching the state
 * make_level() leaves for unused slots. Hand-built selftest fixtures need this
 * because a bare memset leaves slots at (0,0), which move_robots() would treat
 * as live robots sitting on the border. */
static void bg_robots_blank(bg_robots_game *g) {
    int i;
    memset(g, 0, sizeof *g);
    for (i = 0; i < BG_ROBOTS_MAXROBOTS; i++) g->robots[i].y = -1;
}

/* Deterministic, no terminal: exercise placement, chase, collision->heap,
 * scoring, level clear, eaten/teleport-gate. Prints one stable line. */
static int bg_robots_selftest(void) {
    static bg_robots_game gg;
    bg_robots_game *g = &gg;
    int ok = 1;

    /* (1) seeded placement is reproducible and counts match the level. */
    {
        bg_robots_coord r0a, r0b, mea, meb;
        int na, nb;
        memset(g, 0, sizeof *g);
        g->level = 2; g->start_level = 2;
        bg_robots_srand(12345u);
        bg_robots_make_level(g);
        na = g->num_robots; r0a = g->robots[0]; mea = g->me;
        memset(g, 0, sizeof *g);
        g->level = 2; g->start_level = 2;
        bg_robots_srand(12345u);
        bg_robots_make_level(g);
        nb = g->num_robots; r0b = g->robots[0]; meb = g->me;
        if (na != 20 || nb != 20) ok = 0;                 /* level 2 -> 20      */
        if (r0a.y != r0b.y || r0a.x != r0b.x) ok = 0;     /* reproducible       */
        if (mea.y != meb.y || mea.x != meb.x) ok = 0;
        /* every placement is in bounds */
        if (mea.y <= 0 || mea.y >= BG_ROBOTS_YFS ||
            mea.x <= 0 || mea.x >= BG_ROBOTS_XFS) ok = 0;
    }

    /* (2) level cap: level 5+ never exceeds MAXROBOTS. */
    {
        memset(g, 0, sizeof *g);
        g->level = 9; g->start_level = 1;
        bg_robots_srand(7u);
        bg_robots_make_level(g);
        if (g->num_robots != BG_ROBOTS_MAXROBOTS) ok = 0;
    }

    /* (3) a single robot chases the player by one cell per axis. */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->robots[0].y = 5; g->robots[0].x = 14;
        g->field[5][14] = 1;
        g->num_robots = 1;
        bg_robots_move_robots(g);
        /* sign(10-5)=+1 in y, sign(10-14)=-1 in x */
        if (g->robots[0].y != 6 || g->robots[0].x != 13) ok = 0;
        if (g->field[6][13] != 1) ok = 0;
        if (g->dead) ok = 0;
        if (g->num_robots != 1) ok = 0;
    }

    /* (4) two robots converging on the same cell fuse into a heap and score 20
     *     (10 each); the level clears. Player at (10,10): a robot at (8,9) steps
     *     to (9,10) and a robot at (8,11) also steps to (9,10) -- they collide. */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->robots[0].y = 8; g->robots[0].x = 9;  g->field[8][9]  = 1;
        g->robots[1].y = 8; g->robots[1].x = 11; g->field[8][11] = 1;
        g->num_robots = 2;
        bg_robots_move_robots(g);
        if (g->dead) ok = 0;
        if (!g->heap[9][10]) ok = 0;                /* fused into a heap        */
        if (g->num_robots != 0) ok = 0;            /* both scrapped            */
        if (g->score != 20) ok = 0;                /* 10 + 10                  */
    }

    /* (5) a robot stepping onto an existing heap is scrapped on the heap.
     *     Player at (10,10): a robot at (7,8) steps to (8,9), where a heap sits. */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->heap[8][9] = 1;                          /* heap sits at (8,9)       */
        g->robots[0].y = 7; g->robots[0].x = 8; g->field[7][8] = 1; /* ->(8,9) */
        g->num_robots = 1;
        bg_robots_move_robots(g);
        if (!g->heap[8][9]) ok = 0;
        if (g->num_robots != 0) ok = 0;
        if (g->score != 10) ok = 0;
        if (g->field[8][9] != 0) ok = 0;            /* robot removed from count */
    }

    /* (6) a robot reaching the player's cell kills the player. */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->robots[0].y = 9; g->robots[0].x = 10; g->field[9][10] = 1; /* ->(10,10) */
        g->num_robots = 1;
        bg_robots_move_robots(g);
        if (!g->dead) ok = 0;
    }

    /* (7) do_move rejects walking onto a heap and onto a cell adjacent to a live
     *     robot (eaten); accepts a safe step. */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->heap[10][11] = 1;                        /* east cell is a heap      */
        if (bg_robots_do_move(g, 0, 1)) ok = 0;     /* must be rejected         */
        if (g->me.x != 10) ok = 0;                  /* no movement on reject    */
        /* a live robot two cells west makes the west cell "eaten" */
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->robots[0].y = 10; g->robots[0].x = 8; g->field[10][8] = 1;
        g->num_robots = 1;
        if (bg_robots_do_move(g, 0, -1)) ok = 0;    /* stepping to (10,9) eaten */
        if (g->me.x != 10) ok = 0;
        /* but east is safe here */
        if (!bg_robots_do_move(g, 0, 1)) ok = 0;
        if (g->me.x != 11) ok = 0;
    }

    /* (8) must_telep: every reachable cell -- including staying put -- is fatal,
     *     so the only escape is a teleport. Four robots on the inner diagonals
     *     (9,9),(9,11),(11,9),(11,11) around the player at (10,10) block those
     *     four cells and make every other cell of the 3x3 (the four edge moves
     *     and the stay cell) adjacent to a live robot, hence "eaten". */
    {
        bg_robots_blank(g);
        g->me.y = 10; g->me.x = 10;
        g->robots[0].y = 9;  g->robots[0].x = 9;  g->field[9][9]   = 1;
        g->robots[1].y = 9;  g->robots[1].x = 11; g->field[9][11]  = 1;
        g->robots[2].y = 11; g->robots[2].x = 9;  g->field[11][9]  = 1;
        g->robots[3].y = 11; g->robots[3].x = 11; g->field[11][11] = 1;
        g->num_robots = 4;
        if (!bg_robots_must_telep(g)) ok = 0;
    }

    /* (9) waiting accrues a wait bonus: scrap-while-waiting adds to wait_bonus,
     *     and level_bonus folds it into the score. */
    {
        bg_robots_blank(g);
        g->level = 1; g->start_level = 1;
        g->me.y = 10; g->me.x = 10;
        g->waiting = 1;
        g->robots[0].y = 8; g->robots[0].x = 9;  g->field[8][9]  = 1;
        g->robots[1].y = 8; g->robots[1].x = 11; g->field[8][11] = 1;
        g->num_robots = 2;
        bg_robots_move_robots(g);                   /* both fuse at (9,10)      */
        if (g->wait_bonus != 2) ok = 0;
        bg_robots_level_bonus(g);
        /* score 20 from scraps + 2 wait bonus = 22 (no advance bonus on lvl 1) */
        if (g->score != 22) ok = 0;
    }

    printf("robots: selftest %s\n", ok ? "ok" : "FAIL");
    fflush(stdout);
    return ok ? 0 : 1;
}

/* ---- usage -------------------------------------------------------------- */
static int bg_robots_usage(FILE *out, int rc) {
    fputs("usage: robots [--seed N] [--level N] [--quiet]\n"
          "       robots --selftest\n"
          "keys (stdin or tty): y k u / h l / b j n move, . wait, "
          "w wait-out, t teleport, q quit\n", out);
    return rc;
}

/* ---- entry point -------------------------------------------------------- */
static int bsdg_robots(int argc, char **argv) {
    static bg_robots_game gg;
    bg_robots_game *g = &gg;
    long seed = 0, level = 1;
    int have_seed = 0, quiet = 0, i;

    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        if (strcmp(a, "--help") == 0 || strcmp(a, "-h") == 0)
            return bg_robots_usage(stdout, 0);
        if (strcmp(a, "--selftest") == 0)
            return bg_robots_selftest();
        if (strcmp(a, "--quiet") == 0) { quiet = 1; continue; }
        if (strcmp(a, "--seed") == 0) {
            long v;
            if (i + 1 >= argc || bg_robots_parse_int(argv[++i], &v) < 0) {
                fputs("robots: --seed needs an integer\n", stderr);
                return 2;
            }
            seed = v; have_seed = 1; continue;
        }
        if (strcmp(a, "--level") == 0) {
            long v;
            if (i + 1 >= argc || bg_robots_parse_int(argv[++i], &v) < 0 ||
                v < 1 || v > 1000) {
                fputs("robots: --level needs an integer 1..1000\n", stderr);
                return 2;
            }
            level = v; continue;
        }
        if (a[0] == '-' && a[1] != '\0') {
            fprintf(stderr, "robots: unknown option: %s\n", a);
            return 2;
        }
        fprintf(stderr, "robots: unexpected argument: %s\n", a);
        return 2;
    }

    /* Seed: --seed wins; else $BASH_BSDGAMES_SEED; else clock^pid. */
    if (have_seed) {
        bg_robots_srand((uint32_t)seed);
    } else {
        const char *e = getenv("BASH_BSDGAMES_SEED");
        long v;
        if (e && bg_robots_parse_int(e, &v) == 0)
            bg_robots_srand((uint32_t)v);
        else
            bg_robots_srand((uint32_t)time(NULL) ^ (uint32_t)getpid());
    }

    memset(g, 0, sizeof *g);
    g->level = (int)level;
    g->start_level = (int)level;
    bg_robots_make_level(g);

    if (isatty(0))
        return bg_robots_run_interactive(g);
    return bg_robots_run_scripted(g, quiet);
}

/* ===== sail.c ===== */
/* @game sail : age-of-sail naval combat -- maneuver and fire broadsides */
/* bsdgames `sail` (UCB, "wooden ships and iron men"). You command one Man of
 * War on a grid and duel an enemy ship: turn, sail, and let loose broadsides.
 *
 * SCOPE (bounded, deterministic, no curses, no driver process, no state files).
 * The upstream game ships ~33 scenarios, up to ten ships each, a curses screen,
 * and a separate driver process that talks to player processes through a shared
 * /tmp sync file. That whole multi-process/multi-scenario apparatus is OUT of
 * scope here. What this adapter implements is a single faithful one-on-one
 * scenario -- scene 0, "Ranger vs. Drake" (you are the 19-gun American sloop
 * Ranger; the computer sails the 17-gun British Drake) -- with the REAL game
 * mechanics ported from the oracle:
 *   - the ship specs and the wind/range/damage tables (WET, RigTable, HullTable,
 *     AMMO, HDT, HDTrake, QUAL, rangeofshot) taken verbatim as game DATA;
 *   - range()/gunsbear()/portside()/angle() bearing arithmetic (no floating
 *     point in the originals' spirit -- angle() does use the *2.4 ratios);
 *   - maxmove()/maxturns(): how far you may sail and turn given your attitude to
 *     the wind, sail set, and rigging damage; the "in irons" rule;
 *   - movement parsing of an order string like "l3" (turn left, sail 3), the
 *     "turn into the wind stops the move" rule, drift when you make no headway;
 *   - table(): broadside hit resolution -- pick the Rigging/Hull table row by the
 *     hit value and a d6, apply ammo/raking/stern-rake/crew-quality/full-sail
 *     modifiers, then subtract crew/rigging/guns/hull and strike at hull 0;
 *   - a legal computer opponent that closes on you (a bounded best-move search in
 *     the spirit of closeon()/try()) and fires its loaded, in-arc broadsides.
 *
 * No curses: the board is plain text/ANSI. Interactive play is gated on
 * isatty(0). The headless path reads one order-set per stdin line and stops at
 * EOF, when the battle is decided, or after a turn cap -- it never blocks and
 * never needs a real TTY. Randomness (the d6 rolls) comes from a seedable
 * xorshift PRNG: --seed N, else $BASH_BSDGAMES_SEED, else clock^pid. --selftest
 * runs internal checks and prints one stable line.
 *
 * All symbols are static and bg_sail_-prefixed (the file is spliced into
 * bsdgames.c with ~40 other adapters). The entry returns plain ints
 * (0 ok / 1 fail / 2 usage); diagnostics go to stderr; so the file also passes
 * the isolated compile-check harness that has no loadables.h. */

/* ---- signal-number fallbacks (host splice provides <signal.h>) ---------- */
#ifndef SIGHUP
#define SIGHUP  1
#endif
#ifndef SIGINT
#define SIGINT  2
#endif
#ifndef SIGTERM
#define SIGTERM 15
#endif

/* ---- shot / ready bits (mirror the oracle's extern.h) ------------------- */
#define BG_SAIL_L_EMPTY   0
#define BG_SAIL_L_GRAPE   1
#define BG_SAIL_L_CHAIN   2
#define BG_SAIL_L_ROUND   3
#define BG_SAIL_L_DOUBLE  4
#define BG_SAIL_L_EXPLODE 5

#define BG_SAIL_R_EMPTY   0
#define BG_SAIL_R_LOADING 1
#define BG_SAIL_R_DOUBLE  2
#define BG_SAIL_R_LOADED  4
#define BG_SAIL_R_INITIAL 8

#define BG_SAIL_HULL    0
#define BG_SAIL_RIGGING 1

/* ---- deterministic PRNG (xorshift32, seedable) -------------------------- */
static uint32_t bg_sail_rng = 0x9e3779b9u;
static void bg_sail_srand(uint32_t s) {
    bg_sail_rng = s ? s : 0x9e3779b9u;     /* avoid the zero fixed point */
}
static uint32_t bg_sail_rand(void) {
    uint32_t x = bg_sail_rng;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    bg_sail_rng = x;
    return x;
}
/* dieroll(): 1..6, exactly random()%6+1 in the oracle. */
static int bg_sail_dieroll(void) { return (int)(bg_sail_rand() % 6u) + 1; }

/* ---- ship specs (subset of the oracle's specs[]) ------------------------ */
/* Only the two specs the Ranger-vs-Drake scenario needs.  Layout mirrors
 * struct shipspecs: bs fs ta guns class hull qual crew1 crew2 crew3
 * gunL gunR carL carR rig1 rig2 rig3 rig4 pts.  These are game DATA. */
typedef struct {
    int bs, fs, ta;            /* battle speed, full-sail speed, max turns    */
    int guns;                  /* total guns (display)                        */
    int klass;                 /* ship class 1..6 (1 = ship of the line)      */
    int hull;
    int qual;                  /* crew quality 1..5                           */
    int crew1, crew2, crew3;   /* three crew sections                         */
    int gunL, gunR, carL, carR;/* broadside guns / carronades per side        */
    int rig1, rig2, rig3, rig4;/* rigging on up to four masts (-1 = no 4th)   */
    int pts;
} bg_sail_specs;

/* specs[0] Ranger, specs[1] Drake (from globals.c). */
static const bg_sail_specs bg_sail_spec_ranger =
    { 4, 7, 3, 19, 5, 5, 4, 2, 2, 2, 2, 2, 0, 0, 4, 4, 4, 4, 7 };
static const bg_sail_specs bg_sail_spec_drake =
    { 4, 7, 3, 17, 5, 5, 4, 2, 2, 2, 0, 0, 4, 4, 3, 3, 3, 3, 6 };

/* ---- per-ship live state (a flattened struct ship + struct File) -------- */
typedef struct {
    const char *name;
    const bg_sail_specs *base; /* immutable starting specs                    */
    int nationality;           /* 0 = American, 1 = British (index into names)*/
    int sternnum;              /* ship number for the "a0"/"b0" tag           */

    /* mutable specs (damage reduces these) */
    int hull, qual;
    int crew[3];
    int gunL, gunR, carL, carR;
    int rig[4];

    /* position / heading */
    int row, col;
    int dir;                   /* 1..8, 0 = sunk/out of play                  */
    int drift;

    /* gunnery readiness */
    int loadL, loadR;          /* L_* shot type loaded each side              */
    int readyL, readyR;        /* R_* bits                                    */
    int loadwith;              /* computer's preferred next load              */

    /* status */
    int fs;                    /* full sails set                              */
    int struck;                /* has struck colours                          */
    int sink;                  /* sinking                                     */
    int explode;               /* on fire / about to explode                  */
    long points;               /* points scored by this ship                  */
} bg_sail_ship;

/* ---- the whole game state ---------------------------------------------- */
typedef struct {
    bg_sail_ship ship[2];      /* [0] = player (Ranger), [1] = computer (Drake)*/
    int winddir;               /* 1..8                                         */
    int windspeed;             /* 0..7                                         */
    int windchange;
    int turn;
    int quiet;                 /* suppress per-turn board frames              */
    int gameover;
} bg_sail_game;

