static const int NGAMES = (int) (sizeof GAMES / sizeof GAMES[0]);

static const game_ent *
find_game (const char *name)
{
    for (int i = 0; i < NGAMES; i++) if (!strcmp (GAMES[i].name, name)) return &GAMES[i];
    return NULL;
}

static int
bsdg_selftest (void)
{
    /* primes range correctness */
    if (!bsdg_is_prime (2) || !bsdg_is_prime (97) || bsdg_is_prime (1) || bsdg_is_prime (91))
        { builtin_error ("selftest: primality wrong"); return EXECUTION_FAILURE; }
    /* number spelling spot checks */
    char g[128]; spell_group (234, g, sizeof g);
    if (strcmp (g, "two hundred thirty four")) { builtin_error ("selftest: number wrong (%s)", g); return EXECUTION_FAILURE; }
    /* morse table sanity: S=... O=--- */
    if (strcmp (morse_of ('S'), "...") || strcmp (morse_of ('O'), "---"))
        { builtin_error ("selftest: morse wrong"); return EXECUTION_FAILURE; }
    /* rot13 is its own inverse */
    if ((('A' - 'A' + 13) % 26 + 13) % 26 != 0) { builtin_error ("selftest: rot13 wrong"); return EXECUTION_FAILURE; }
    printf ("bsdgames selftest OK (%d games)\n", NGAMES);
    return EXECUTION_SUCCESS;
}

int
bsdgames_builtin (WORD_LIST *list)
{
    if (!list) { builtin_error ("subcommand or game required (try list)"); return EX_USAGE; }
    /* The headless games read stdin with fgets. A builtin does not fork, so a
       stale EOF flag from a previous invocation would make the next game read
       nothing and exit 0 without playing. */
    clearerr (stdin);
    const char *cmd = list->word->word;

    if (!strcmp (cmd, "--help") || !strcmp (cmd, "-h")) { builtin_usage (); return EXECUTION_SUCCESS; }
    if (!strcmp (cmd, "list")) {
        for (int i = 0; i < NGAMES; i++) printf ("%s\n", GAMES[i].name);
        return EXECUTION_SUCCESS;
    }
    if (!strcmp (cmd, "paths")) {
        const char *st = getenv ("BASH_BSDGAMES_STATE_ROOT");
        printf ("data=%s\ndocs=%s\nstate=%s\n", BSDG_DATA_ROOT, BSDG_DOCS_ROOT, st && *st ? st : BSDG_STATE_DFL);
        return EXECUTION_SUCCESS;
    }
    if (!strcmp (cmd, "info")) {
        if (!list->next) { builtin_error ("info: GAME required"); return EX_USAGE; }
        const game_ent *g = find_game (list->next->word->word);
        if (!g) { builtin_error ("info: unknown game: %s", list->next->word->word); return EXECUTION_FAILURE; }
        printf ("%s - %s\n", g->name, g->desc);
        return EXECUTION_SUCCESS;
    }
    if (!strcmp (cmd, "selftest")) return bsdg_selftest ();

    /* otherwise: dispatch cmd as a game with the remaining args */
    const game_ent *g = find_game (cmd);
    if (!g) { builtin_error ("unknown game or subcommand: %s (try list)", cmd); return EX_USAGE; }
    int argc; char **argv = bsdg_argv (list->next, &argc);
    if (!argv) { builtin_error ("out of memory"); return EXECUTION_FAILURE; }
    int rr = g->fn (argc, argv);
    free (argv);
    return rr;
}

char *bsdgames_doc[] = {
    "Runtime boundary + adapters for the BSD games set.",
    "",
    "    bsdgames list            list available games",
    "    bsdgames info GAME       describe a game",
    "    bsdgames paths           data/docs/state roots",
    "    bsdgames selftest        internal checks, exit 0 on success",
    "    bsdgames GAME [ARGS...]  run a game adapter",
    "",
    "Per-game .sh stubs run `builtin bsdgames GAME \"$@\"`. This slice ships",
    "primes, number, morse, caesar, and rot13; TUI games are added as further",
    "adapters. State writes are opt-in; STATE root via BASH_BSDGAMES_STATE_ROOT.",
    (char *) NULL
};

struct builtin bsdgames_struct = {
    "bsdgames",
    bsdgames_builtin,
    BUILTIN_ENABLED,
    bsdgames_doc,
    "bsdgames list|info GAME|paths|selftest|GAME [ARGS...]",
    0
};
